func (s *Store) CreateAssignment(ctx context.Context, a *models.Assignment) error {
	var workerID, fromLoc, toLoc, nodeID, incomingFrom, outgoingTo, labID, expectedST interface{}
	if a.WorkerID != nil {
		workerID = *a.WorkerID
	}
	if a.FromLocationID != nil {
		fromLoc = *a.FromLocationID
	}
	if a.ToLocationID != nil {
		toLoc = *a.ToLocationID
	}
	if a.NodeID != nil {
		nodeID = *a.NodeID
	}
	if a.IncomingFromLocationID != nil {
		incomingFrom = *a.IncomingFromLocationID
	}
	if a.OutgoingToLocationID != nil {
		outgoingTo = *a.OutgoingToLocationID
	}
	if a.LaboratoryID != nil {
		labID = *a.LaboratoryID
	}
	if a.ExpectedSampleTypeID != nil {
		expectedST = *a.ExpectedSampleTypeID
	}
