	return s.db.QueryRowContext(ctx, `
		INSERT INTO locations (id, name, latitude, longitude, coverage_km, handling_minutes, active, functions)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8) RETURNING id`,
		l.ID, l.Name, l.Coordinate.Latitude, l.Coordinate.Longitude, l.CoverageKm, l.HandlingMinutes, l.Active, funcs).Scan(&l.ID)
