func (s *Store) SetLocationFunctionStatus(ctx context.Context, id string, function string, active bool) error {
	var funcs []byte
	err := s.db.QueryRowContext(ctx, `SELECT functions FROM locations WHERE id=$1`, id).Scan(&funcs)
	if err != nil {
		return err
	}
