		e.AuditID, e.ActorID, e.Role, e.ActorRole, e.Action, e.EntityType, e.EntityID, e.Success, e.OccurredAt, e.Details)
	return err
}

func (s *Store) SearchAudit(ctx context.Context, q models.AuditSearchParams) (*models.AuditSearchResult, error) {
	where := "WHERE 1=1"
	args := []interface{}{}
	argIdx := 1

	if q.ActorID != "" {
		where += fmt.Sprintf(" AND actor_id = $%d", argIdx)
		args = append(args, q.ActorID)
		argIdx++
	}
	if q.EntityType != "" {
		where += fmt.Sprintf(" AND entity_type = $%d", argIdx)
		args = append(args, q.EntityType)
		argIdx++
	}
	if q.EntityID != "" {
		where += fmt.Sprintf(" AND entity_id = $%d", argIdx)
		args = append(args, q.EntityID)
		argIdx++
	}
	if q.Action != "" {
		where += fmt.Sprintf(" AND action = $%d", argIdx)
		args = append(args, q.Action)
		argIdx++
	}
	if q.Role != "" {
		where += fmt.Sprintf(" AND role = $%d", argIdx)
		args = append(args, q.Role)
		argIdx++
	}
	if q.Success != nil {
		where += fmt.Sprintf(" AND success = $%d", argIdx)
		args = append(args, *q.Success)
		argIdx++
	}
	if q.FromTime != nil {
		where += fmt.Sprintf(" AND occurred_at >= $%d", argIdx)
		args = append(args, *q.FromTime)
		argIdx++
	}
	if q.ToTime != nil {
		where += fmt.Sprintf(" AND occurred_at <= $%d", argIdx)
		args = append(args, *q.ToTime)
		argIdx++
	}

	var total int
	countQuery := fmt.Sprintf("SELECT COUNT(*) FROM audit_trail %s", where)
	s.db.QueryRowContext(ctx, countQuery, args...).Scan(&total)

	order := "ORDER BY occurred_at DESC"
	if q.Order == "oldest_first" {
		order = "ORDER BY occurred_at ASC"
	}

	limit := q.Limit
	if limit <= 0 {
		limit = 50
	}

	query := fmt.Sprintf("SELECT id, actor_id, role, actor_role, action, entity_type, entity_id, success, occurred_at, details FROM audit_trail %s %s LIMIT $%d OFFSET $%d",
		where, order, argIdx, argIdx+1)
	args = append(args, limit, q.Offset)

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var entries []models.AuditEntry
	for rows.Next() {
		var e models.AuditEntry
		rows.Scan(&e.AuditID, &e.ActorID, &e.Role, &e.ActorRole, &e.Action, &e.EntityType, &e.EntityID, &e.Success, &e.OccurredAt, &e.Details)
		e.AuditID2 = e.AuditID
		e.ActorID2 = e.ActorID
		e.EntityType2 = e.EntityType
		e.EntityID2 = e.EntityID
		e.OccurredAt2 = e.OccurredAt
		entries = append(entries, e)
	}

	result := &models.AuditSearchResult{
		Entries:  entries,
		Total:    total,
		Returned: len(entries),
		Offset:   q.Offset,
		Limit:    limit,
		Order:    q.Order,
		HasMore:  q.Offset+limit < total,
	}
	if result.HasMore {
		no := q.Offset + limit
		result.NextOffset = &no
	}
	return result, nil
}

type AuditSearchParams struct {
	ActorID    string
	EntityType string
	EntityID   string
	Action     string
	Role       string
	Success    *bool
	FromTime   *time.Time
	ToTime     *time.Time
	Limit      int
	Offset     int
	Order      string
}

// --- Realtime Events ---

func (s *Store) WriteRealtimeEvent(ctx context.Context, eventType, entityType, entityID, payload string) (int64, error) {
	var id int64
	err := s.db.QueryRowContext(ctx, `INSERT INTO realtime_events (event_type, entity_type, entity_id, payload) VALUES ($1,$2,$3,$4) RETURNING id`,
		eventType, entityType, entityID, payload).Scan(&id)
	if err != nil {
		return 0, err
	}
	// Publish to Redis for live subscribers
	s.redis.Publish(ctx, "events", fmt.Sprintf(`{"id":%d,"type":"%s","entityType":"%s","entityId":"%s","payload":%s,"createdAt":"%s"}`,
		id, eventType, entityType, entityID, payload, time.Now().UTC().Format(time.RFC3339)))
	return id, nil
}

func (s *Store) GetRealtimeEventsSince(ctx context.Context, since int64) ([]models.RealtimeEvent, int64, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT id, event_type, entity_type, entity_id, payload, created_at FROM realtime_events WHERE id > $1 ORDER BY id LIMIT 100`, since)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	var events []models.RealtimeEvent
	var maxID int64 = since
	for rows.Next() {
		var e models.RealtimeEvent
		var payload string
		rows.Scan(&e.ID, &e.Type, &e.EntityType, &e.EntityID, &payload, &e.CreatedAt)
		e.Payload = payload
		events = append(events, e)
		if e.ID > maxID {
			maxID = e.ID
		}
	}
	return events, maxID, nil
}

