	}
	json.Unmarshal(roles, &u.Roles)
	json.Unmarshal(quals, &u.Qualifications)
	json.Unmarshal(certs, &u.Certifications)
	if assignedLoc.Valid {
		u.AssignedLocationID = &assignedLoc.String
	}
