func (s *Store) GetLocationCapacity(ctx context.Context, locationID string) (models.Capacity, error) {
	var cap models.Capacity
	var capUnits, cooledCap, reserved, cooledReserved int
	err := s.db.QueryRowContext(ctx, `
		SELECT COALESCE(capacity_units,0), COALESCE(cooled_capacity_units,0), COALESCE(reserved_units,0), COALESCE(cooled_reserved_units,0)
		FROM locations WHERE id=$1`, locationID).Scan(&capUnits, &cooledCap, &reserved, &cooledReserved)
	if err != nil {
		return cap, err
	}
	cap.CapacityUnits = capUnits
	cap.CooledCapacityUnits = cooledCap
	cap.ReservedUnits = reserved
	cap.CooledReservedUnits = cooledReserved
	cap.AvailableUnits = capUnits - reserved
	cap.CooledAvailableUnits = cooledCap - cooledReserved
	return cap, nil
}

func (s *Store) ReserveLocationCapacity(ctx context.Context, locationID, journeyID string, units, cooledUnits int) error {
	_, err := s.db.ExecContext(ctx, `
		UPDATE locations SET reserved_units = reserved_units + $1, cooled_reserved_units = cooled_reserved_units + $2 WHERE id=$3`,
		units, cooledUnits, locationID)
	if err != nil {
		return err
	}
	_, err = s.db.ExecContext(ctx, `INSERT INTO location_capacity_reservations (location_id, journey_id, units, cooled_units) VALUES ($1,$2,$3,$4)`,
		locationID, journeyID, units, cooledUnits)
	return err
}

func (s *Store) ReleaseLocationCapacity(ctx context.Context, journeyID string) error {
	rows, err := s.db.QueryContext(ctx, `SELECT location_id, units, cooled_units FROM location_capacity_reservations WHERE journey_id=$1`, journeyID)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var locID string
		var units, cooled int
		rows.Scan(&locID, &units, &cooled)
		s.db.ExecContext(ctx, `UPDATE locations SET reserved_units = GREATEST(reserved_units - $1, 0), cooled_reserved_units = GREATEST(cooled_reserved_units - $2, 0) WHERE id=$3`,
			units, cooled, locID)
	}
	s.db.ExecContext(ctx, `DELETE FROM location_capacity_reservations WHERE journey_id=$1`, journeyID)
	return nil
}

func (s *Store) SetLocationCapacity(ctx context.Context, id string, units, cooledUnits int) error {
	_, err := s.db.ExecContext(ctx, `UPDATE locations SET capacity_units=$1, cooled_capacity_units=$2 WHERE id=$3`, units, cooledUnits, id)
