// --- Sessions (Redis) ---

func (s *Store) CreateSession(ctx context.Context, token, userID, activeRole string, ttl time.Duration) error {
	data := map[string]string{"userId": userID, "activeRole": activeRole}
	b, _ := json.Marshal(data)
	return s.redis.Set(ctx, "session:"+token, b, ttl).Err()
}

func (s *Store) GetSession(ctx context.Context, token string) (userID, activeRole string, err error) {
	b, err := s.redis.Get(ctx, "session:"+token).Bytes()
	if err != nil {
		return "", "", err
	}
	var data map[string]string
	json.Unmarshal(b, &data)
	return data["userId"], data["activeRole"], nil
}

func (s *Store) DeleteSession(ctx context.Context, token string) error {
	return s.redis.Del(ctx, "session:"+token).Err()
}

func (s *Store) UpdateSessionRole(ctx context.Context, token, role string) error {
	b, err := s.redis.Get(ctx, "session:"+token).Bytes()
	if err != nil {
		return err
	}
	var data map[string]string
	json.Unmarshal(b, &data)
	data["activeRole"] = role
	newB, _ := json.Marshal(data)
	ttl := s.redis.TTL(ctx, "session:"+token).Val()
	return s.redis.Set(ctx, "session:"+token, newB, ttl).Err()
}

// --- Idempotency ---

func (s *Store) CheckIdempotency(ctx context.Context, key string) ([]byte, bool, error) {
	b, err := s.redis.Get(ctx, "idem:"+key).Bytes()
	if err == redis.Nil {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, err
	}
	return b, true, nil
}

func (s *Store) SetIdempotency(ctx context.Context, key string, response []byte) error {
	return s.redis.Set(ctx, "idem:"+key, response, 24*time.Hour).Err()
}

func (s *Store) SaveIdempotencyDB(ctx context.Context, key string, response []byte) {
	s.db.ExecContext(ctx, `INSERT INTO idempotency_keys (key, response) VALUES ($1, $2) ON CONFLICT DO NOTHING`, key, response)
}

