// CreateCollectionRequest
func (h *Handler) CreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	var req struct {
		RequesterID           string            `json:"requesterId"`
		Origin                models.Coordinate `json:"origin"`
		OriginType            string            `json:"originType"`
		OriginNodeID          *string           `json:"originNodeId"`
		RequestedAt           time.Time         `json:"requestedAt"`
		DeliveryDeadline      time.Time         `json:"deliveryDeadline"`
		EarliestCollectionAt  time.Time         `json:"earliestCollectionAt"`
		LatestCollectionAt    time.Time         `json:"latestCollectionAt"`
		SampleTypeID          string            `json:"sampleTypeId"`
		ContainerType         string            `json:"containerType"`
		TemperatureMinC       *float64          `json:"temperatureMinC"`
		TemperatureMaxC       *float64          `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string        `json:"incompatibleSampleTypes"`
		IdempotencyKey        string            `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	if req.IdempotencyKey == "" {
		errResp(w, 400, "idempotency_required", "idempotencyKey required")
		return
	}

	if cached, found, _ := h.Store.CheckIdempotency(r.Context(), req.IdempotencyKey); found {
		var resp map[string]interface{}
		json.Unmarshal(cached, &resp)
		respond(w, 201, resp)
		return
	}

	// Check serviceability
	svcResult, err := h.Service.CheckServiceability(r.Context(), req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, req.EarliestCollectionAt, req.LatestCollectionAt, req.DeliveryDeadline)
	if err != nil || !svcResult.Serviceable {
		reason := "not serviceable"
		if err != nil {
			reason = err.Error()
		} else {
			reason = svcResult.Reason
		}
		errResp(w, 409, "state_snapshot_changed", reason)
		return
	}

	requestID := uuid.New().String()
	sampleID := uuid.New().String()

	sm := &models.Sample{
		ID:                      sampleID,
		RequestID:               requestID,
		RequesterID:             req.RequesterID,
		Status:                  "requested",
		Sealed:                  false,
		Origin:                  req.Origin,
		OriginType:              req.OriginType,
		OriginNodeID:            req.OriginNodeID,
		RequestedAt:             req.RequestedAt,
		DeliveryDeadline:        req.DeliveryDeadline,
		SampleTypeID:            req.SampleTypeID,
		ContainerType:           req.ContainerType,
		TemperatureMinC:         req.TemperatureMinC,
		TemperatureMaxC:         req.TemperatureMaxC,
		IncompatibleSampleTypes: req.IncompatibleSampleTypes,
		Serviceability:          svcResult.Serviceable,
		ServiceabilityReason:    svcResult.Reason,
		State:                   "requested",
		TargetLaboratoryID:      svcResult.TargetLaboratoryID,
		LocationStale:           true,
		EarliestCollectionAt:    req.EarliestCollectionAt,
		LatestCollectionAt:      req.LatestCollectionAt,
	}

	if err := h.Store.CreateSample(r.Context(), sm); err != nil {
		errResp(w, 500, "internal_error", "failed to create sample")
		return
	}

	// Create journey if serviceable
	var journeyID *string
	if svcResult.Serviceable && svcResult.TargetLaboratoryID != nil {
		j := &models.Journey{
			ID:                   uuid.New().String(),
			PlanVersion:          1,
			RouteMode:            "direct",
			Status:               "planned",
			SampleIDs:            []string{sampleID},
			EstimatedDeliveryAt:  svcResult.EstimatedArrivalAt,
			TotalCostUnits:       0,
			CapacityUsed:         1,
			CapacityAvailable:    1,
			Valid:                true,
			CollectionAssignmentIDs: []string{},
			NodeAssignmentIDs:       []string{},
			LaboratoryAssignmentIDs: []string{},
		}

		// Add stops
		collectionStop := models.JourneyStop{
			StopID:     uuid.New().String(),
			LocationID: *svcResult.TargetLaboratoryID, // using nearest collection point
			StopType:   "collection",
			Sequence:   1,
			EstimatedAt: req.EarliestCollectionAt,
			Coordinate: &req.Origin,
		}
		labStop := models.JourneyStop{
			StopID:      uuid.New().String(),
			LocationID:  *svcResult.TargetLaboratoryID,
			StopType:    "laboratory",
			Sequence:    2,
			EstimatedAt: req.DeliveryDeadline,
		}
		j.OrderedStops = []models.JourneyStop{collectionStop, labStop}

		if err := h.Store.CreateJourney(r.Context(), j); err != nil {
			log.Printf("journey creation error: %v", err)
		} else {
			journeyID = &j.ID
			sm.ActiveJourneyID = journeyID
			sm.Status = "planned"
			sm.State = "planned"
			h.Store.UpdateSample(r.Context(), sm)
		}
	}

	// Write timeline
	now := time.Now().UTC()
	h.Store.AddSampleTimeline(r.Context(), models.TimelineEntry{
		EventID:    uuid.New().String(),
		Action:     "request_created",
		ActorID:    req.RequesterID,
		Role:       "requester",
		EntityType: "sample",
		EntityID:   sampleID,
		Success:    true,
		OccurredAt: now,
		Details:    "Collection request created",
	})

	h.writeAudit(req.RequesterID, middleware.GetRole(r.Context()), "request.created", "sample", sampleID, true, "")

	resp := map[string]interface{}{
		"data": map[string]interface{}{
			"requestId":            requestID,
			"sampleId":             sampleID,
			"serviceability":       svcResult.Serviceable,
			"serviceabilityReason": svcResult.Reason,
			"activeAssignmentIds":  []string{},
			"earliestCollectionAt": req.EarliestCollectionAt,
			"latestCollectionAt":   req.LatestCollectionAt,
			"alreadySealed":        false,
			"originType":           req.OriginType,
		},
	}

	if journeyID != nil {
		resp["data"].(map[string]interface{})["journeyId"] = *journeyID
	}
	if svcResult.TargetLaboratoryID != nil {
		resp["data"].(map[string]interface{})["targetLaboratoryId"] = *svcResult.TargetLaboratoryID
	}

	b, _ := json.Marshal(resp)
	h.Store.SetIdempotency(r.Context(), req.IdempotencyKey, b)

	respond(w, 201, resp)
}

// IngestPresealedSample
func (h *Handler) IngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	var req struct {
		RequesterID           string            `json:"requesterId"`
		Origin                models.Coordinate `json:"origin"`
		OriginType            string            `json:"originType"`
		OriginNodeID          *string           `json:"originNodeId"`
		RequestedAt           time.Time         `json:"requestedAt"`
		DeliveryDeadline      time.Time         `json:"deliveryDeadline"`
		EarliestCollectionAt  time.Time         `json:"earliestCollectionAt"`
		LatestCollectionAt    time.Time         `json:"latestCollectionAt"`
		SampleTypeID          string            `json:"sampleTypeId"`
		ContainerType         string            `json:"containerType"`
		TemperatureMinC       *float64          `json:"temperatureMinC"`
		TemperatureMaxC       *float64          `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string        `json:"incompatibleSampleTypes"`
		IdempotencyKey        string            `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	if req.IdempotencyKey == "" {
		errResp(w, 400, "idempotency_required", "idempotencyKey required")
		return
	}

	if req.OriginType == "home" {
		errResp(w, 400, "invalid_json", "pre-sealed samples must originate from a clinic or node")
		return
	}

	if cached, found, _ := h.Store.CheckIdempotency(r.Context(), req.IdempotencyKey); found {
		var resp map[string]interface{}
		json.Unmarshal(cached, &resp)
		respond(w, 201, resp)
		return
	}

	requestID := uuid.New().String()
	sampleID := uuid.New().String()

	sm := &models.Sample{
		ID:                      sampleID,
		RequestID:               requestID,
		RequesterID:             req.RequesterID,
		Status:                  "collected",
		Sealed:                  true,
		Origin:                  req.Origin,
		OriginType:              req.OriginType,
		OriginNodeID:            req.OriginNodeID,
		RequestedAt:             req.RequestedAt,
		DeliveryDeadline:        req.DeliveryDeadline,
		SampleTypeID:            req.SampleTypeID,
		ContainerType:           req.ContainerType,
		TemperatureMinC:         req.TemperatureMinC,
		TemperatureMaxC:         req.TemperatureMaxC,
		IncompatibleSampleTypes: req.IncompatibleSampleTypes,
		Serviceability:          true,
		ServiceabilityReason:    "pre-sealed",
		State:                   "collected",
		CurrentHolderID:         &req.RequesterID,
		LocationStale:           false,
		EarliestCollectionAt:    req.EarliestCollectionAt,
		LatestCollectionAt:      req.LatestCollectionAt,
	}

	if err := h.Store.CreateSample(r.Context(), sm); err != nil {
		errResp(w, 500, "internal_error", "failed to create sample")
		return
	}

	h.Store.AddSampleTimeline(r.Context(), models.TimelineEntry{
		EventID:    uuid.New().String(),
		Action:     "presealed_ingested",
		ActorID:    req.RequesterID,
		Role:       middleware.GetRole(r.Context()),
		EntityType: "sample",
		EntityID:   sampleID,
		Success:    true,
		OccurredAt: time.Now().UTC(),
		Details:    "Pre-sealed sample registered",
	})

	resp := map[string]interface{}{
		"data": map[string]interface{}{
			"requestId":            requestID,
			"sampleId":             sampleID,
			"serviceability":       true,
			"serviceabilityReason": "pre-sealed",
			"activeAssignmentIds":  []string{},
			"earliestCollectionAt": req.EarliestCollectionAt,
			"latestCollectionAt":   req.LatestCollectionAt,
			"alreadySealed":        true,
			"originType":           req.OriginType,
		},
	}

	b, _ := json.Marshal(resp)
	h.Store.SetIdempotency(r.Context(), req.IdempotencyKey, b)
	respond(w, 201, resp)
}

// CollectAndSealSample
func (h *Handler) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		CollectedAt          time.Time `json:"collectedAt"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	userID := middleware.GetUserID(r.Context())

	sm, err := h.Store.GetSample(r.Context(), req.SampleID)
	if err != nil {
		errResp(w, 404, "not_found", "sample not found")
		return
	}

	// Determine handling compliance
	st, err := h.Store.GetSampleType(r.Context(), sm.SampleTypeID)
	compliant := true
	if err == nil {
		if st.TemperatureMinC != nil && req.ObservedTemperatureC < *st.TemperatureMinC {
			compliant = false
		}
		if st.TemperatureMaxC != nil && req.ObservedTemperatureC > *st.TemperatureMaxC {
			compliant = false
		}
	}

	sm.Status = "collected"
	sm.Sealed = true
	sm.State = "collected"
	sm.ContainerType = req.ContainerType
	sm.CurrentHolderID = &userID
	sm.LocationStale = false

	if err := h.Store.UpdateSample(r.Context(), sm); err != nil {
		errResp(w, 500, "internal_error", "update failed")
		return
	}

	h.Store.AddSampleTimeline(r.Context(), models.TimelineEntry{
		EventID:    uuid.New().String(),
		Action:     "collected_and_sealed",
		ActorID:    userID,
		Role:       middleware.GetRole(r.Context()),
		EntityType: "sample",
		EntityID:   sm.ID,
		Success:    true,
		OccurredAt: req.CollectedAt,
		Details:    "Sample collected and sealed",
	})

	h.writeAudit(userID, middleware.GetRole(r.Context()), "sample.collected", "sample", sm.ID, true, "")

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"sampleId":          sm.ID,
			"status":            sm.Status,
			"currentHolderId":   userID,
			"sealedAt":          req.CollectedAt,
			"handlingCompliant": compliant,
		},
	})
}

// AcceptAssignment
func (h *Handler) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	if req.IdempotencyKey == "" {
		errResp(w, 400, "idempotency_required", "idempotencyKey required")
		return
	}

	if cached, found, _ := h.Store.CheckIdempotency(r.Context(), req.IdempotencyKey); found {
		var resp map[string]interface{}
		json.Unmarshal(cached, &resp)
		respond(w, 201, resp)
		return
	}

	userID := middleware.GetUserID(r.Context())
	role := middleware.GetRole(r.Context())

	a, err := h.Store.GetAssignment(r.Context(), req.AssignmentID)
	if err != nil {
		errResp(w, 404, "not_found", "assignment not found")
		return
	}

	if a.Status != "offered" {
		errResp(w, 409, "assignment_inactive", "assignment is not in offered state")
		return
	}

	if a.WorkerID != nil && *a.WorkerID != userID {
		errResp(w, 403, "ineligible_worker", "assignment not offered to this worker")
		return
	}

	if a.OfferExpiresAt != nil && time.Now().After(*a.OfferExpiresAt) {
		errResp(w, 409, "offer_not_available", "offer has expired")
		return
	}

	a.Status = "accepted"
	a.WorkerID = &userID
	a.OfferExpiresAt = nil

	if err := h.Store.UpdateAssignment(r.Context(), a); err != nil {
		errResp(w, 500, "internal_error", "update failed")
		return
	}

	// Update sample state if collection assignment
	sm, _ := h.Store.GetSample(r.Context(), a.SampleID)
	if sm != nil {
		sm.State = "assigned"
		sm.CurrentHolderID = &userID
		h.Store.UpdateSample(r.Context(), sm)
	}

	h.Store.AddAssignmentTimeline(r.Context(), models.TimelineEntry{
		EventID:    uuid.New().String(),
		Action:     "assignment_accepted",
		ActorID:    userID,
		Role:       role,
		EntityType: "assignment",
		EntityID:   a.ID,
		Success:    true,
		OccurredAt: time.Now().UTC(),
		Details:    "Assignment accepted",
	})

	h.Store.IncrementWorkerAssignment(r.Context(), userID)
	h.writeAudit(userID, role, "assignment.accepted", "assignment", a.ID, true, "")

	resp := map[string]interface{}{
		"data": map[string]interface{}{
			"assignmentId": a.ID,
			"workerId":     userID,
			"status":       "accepted",
		},
	}
	b, _ := json.Marshal(resp)
	h.Store.SetIdempotency(r.Context(), req.IdempotencyKey, b)
	respond(w, 201, resp)
}

