// ListRoleWork
func (h *Handler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	userID := middleware.GetUserID(r.Context())

	work := models.RoleWork{
		Pending:    []interface{}{},
		InProgress: []interface{}{},
		Completed:  []interface{}{},
	}

	switch req.Role {
	case "requester":
		samples, _ := h.Store.ListSamples(r.Context())
		for _, sm := range samples {
			if sm.RequesterID != userID {
				continue
			}
			wi := models.SampleWorkItem{
				Kind:                 "sample",
				SampleID:             sm.ID,
				SampleID2:            sm.ID,
				RequestID:            sm.RequestID,
				Status:               sm.Status,
				Serviceability:       sm.Serviceability,
				RequestedAt:          sm.RequestedAt,
				DeliveryDeadline:     sm.DeliveryDeadline,
				EarliestCollectionAt: sm.EarliestCollectionAt,
				LatestCollectionAt:   sm.LatestCollectionAt,
				ActiveJourneyID:      sm.ActiveJourneyID,
				CurrentHolderID:      sm.CurrentHolderID,
				RequesterID:          &sm.RequesterID,
				History:              sm.Timeline,
				LocationStale:        sm.LocationStale,
				LocationRecordedAt:   sm.LocationRecordedAt,
			}
			wi.JourneyID = sm.ActiveJourneyID
			wi.LaboratoryID = sm.TargetLaboratoryID

			switch sm.Status {
			case "requested", "planned":
				work.Pending = append(work.Pending, wi)
			case "collected", "assigned", "in_transit":
				work.InProgress = append(work.InProgress, wi)
			case "received", "completed":
				work.Completed = append(work.Completed, wi)
			default:
				work.InProgress = append(work.InProgress, wi)
			}
		}

	case "certified_collection_professional", "relay_courier", "node_handler", "laboratory_intake_operator":
		// Get assignments for this user
		rows, _ := h.Store.DB().QueryContext(r.Context(), `SELECT id FROM assignments WHERE worker_id=$1`, userID)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var aID string
				rows.Scan(&aID)
				a, err := h.Store.GetAssignment(r.Context(), aID)
				if err != nil {
					continue
				}
				wi := models.AssignmentWorkItem{
					Kind:                   "assignment",
					AssignmentID:           a.ID,
					AssignmentID2:          a.ID,
					SampleID:               a.SampleID,
					SampleID2:              a.SampleID,
					Status:                 a.Status,
					JourneyID:              &a.JourneyID,
					FromLocationID:         a.FromLocationID,
					ToLocationID:           a.ToLocationID,
					Sequence:               a.Sequence,
					OfferExpiresAt:         a.OfferExpiresAt,
					DestinationCapacity:    a.DestinationCapacity,
					NodeID:                 a.NodeID,
					IncomingFromLocationID: a.IncomingFromLocationID,
					OutgoingToLocationID:   a.OutgoingToLocationID,
					LaboratoryID:           a.LaboratoryID,
					ExpectedSampleTypeID:   a.ExpectedSampleTypeID,
					History:                a.History,
				}

				switch a.Status {
				case "offered":
					work.Pending = append(work.Pending, wi)
				case "accepted", "in_progress":
					work.InProgress = append(work.InProgress, wi)
				case "completed", "declined":
					work.Completed = append(work.Completed, wi)
				default:
					work.Pending = append(work.Pending, wi)
				}
			}
		}

	case "dispatcher", "administrator":
		// All samples, journeys, assignments visible
		samples, _ := h.Store.ListSamples(r.Context())
		for _, sm := range samples {
			wi := models.SampleWorkItem{
				Kind:                 "sample",
				SampleID:             sm.ID,
				SampleID2:            sm.ID,
				RequestID:            sm.RequestID,
				Status:               sm.Status,
				Serviceability:       sm.Serviceability,
				RequestedAt:          sm.RequestedAt,
				DeliveryDeadline:     sm.DeliveryDeadline,
				EarliestCollectionAt: sm.EarliestCollectionAt,
				LatestCollectionAt:   sm.LatestCollectionAt,
				ActiveJourneyID:      sm.ActiveJourneyID,
				CurrentHolderID:      sm.CurrentHolderID,
				RequesterID:          &sm.RequesterID,
				History:              sm.Timeline,
				LocationStale:        sm.LocationStale,
				LocationRecordedAt:   sm.LocationRecordedAt,
			}
			wi.JourneyID = sm.ActiveJourneyID
			wi.LaboratoryID = sm.TargetLaboratoryID

			switch sm.Status {
			case "requested", "planned":
				work.Pending = append(work.Pending, wi)
			case "collected", "assigned", "in_transit":
				work.InProgress = append(work.InProgress, wi)
			case "received", "completed":
				work.Completed = append(work.Completed, wi)
			default:
				work.InProgress = append(work.InProgress, wi)
			}
		}
	}

	respond(w, 200, map[string]interface{}{"data": work})
}

// CancelJourney
func (h *Handler) CancelJourney(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID          string `json:"journeyId"`
		ExpectedPlanVersion int   `json:"expectedPlanVersion"`
		Reason             string `json:"reason"`
		IdempotencyKey     string `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	j, err := h.Store.GetJourney(r.Context(), req.JourneyID)
	if err != nil {
		errResp(w, 404, "not_found", "journey not found")
		return
	}

	if j.PlanVersion != req.ExpectedPlanVersion {
		errResp(w, 409, "state_snapshot_changed", "plan version mismatch")
		return
	}

	j.Status = "cancelled"
	j.PlanVersion++
	h.Store.UpdateJourneyStatus(r.Context(), j.ID, "cancelled")
	h.Store.UpdateJourneyPlanVersion(r.Context(), j.ID, j.PlanVersion)

	// Update associated samples
	for _, sid := range j.SampleIDs {
		sm, _ := h.Store.GetSample(r.Context(), sid)
		if sm != nil && sm.Status != "received" {
			sm.Status = "cancelled"
			sm.State = "cancelled"
			h.Store.UpdateSample(r.Context(), sm)
		}
	}

	h.Store.ReleaseLocationCapacity(r.Context(), j.ID)

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"journeyId": j.ID,
			"status":    "cancelled",
			"sampleIds": j.SampleIDs,
		},
	})
}

// RerouteJourney
func (h *Handler) RerouteJourney(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID          string `json:"journeyId"`
		ExpectedPlanVersion int   `json:"expectedPlanVersion"`
		Reason             string `json:"reason"`
		IdempotencyKey     string `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	j, err := h.Store.GetJourney(r.Context(), req.JourneyID)
	if err != nil {
		errResp(w, 404, "not_found", "journey not found")
		return
	}

	if j.PlanVersion != req.ExpectedPlanVersion {
		errResp(w, 409, "state_snapshot_changed", "plan version mismatch")
		return
	}

	replanStatus := "replanned"
	j.ReplanStatus = &replanStatus
	j.PlanVersion++
	h.Store.UpdateJourneyStatus(r.Context(), j.ID, "replanned")
	h.Store.UpdateJourneyPlanVersion(r.Context(), j.ID, j.PlanVersion)

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"journeyId":   j.ID,
			"replanStatus": replanStatus,
		},
	})
}

// SplitJourney
func (h *Handler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID          string   `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		SampleIDs          []string `json:"sampleIds"`
		IdempotencyKey     string   `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	// Simple implementation: create a new journey with the specified samples
	newJourney := &models.Journey{
		ID:                    uuid.New().String(),
		ParentJourneyID:       &req.JourneyID,
		PlanVersion:           1,
		RouteMode:             "direct",
		Status:                "planned",
		SampleIDs:             req.SampleIDs,
		Valid:                 true,
		CollectionAssignmentIDs: []string{},
		NodeAssignmentIDs:       []string{},
		LaboratoryAssignmentIDs: []string{},
	}

	if err := h.Store.CreateJourney(r.Context(), newJourney); err != nil {
		errResp(w, 500, "internal_error", "split journey failed")
		return
	}

	origJourney, _ := h.Store.GetJourney(r.Context(), req.JourneyID)
	if origJourney != nil {
		// Remove split samples from original
		splitID := newJourney.ID
		origJourney.SplitJourney = &splitID
		h.Store.UpdateJourneyStatus(r.Context(), origJourney.ID, "split")
	}

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"journey":      newJourney,
			"splitJourney": newJourney,
		},
	})
}

// MergeJourneys
func (h *Handler) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	var req struct {
		TargetJourneyID    string   `json:"targetJourneyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		SourceJourneyIDs   []string `json:"sourceJourneyIds"`
		IdempotencyKey     string   `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	target, err := h.Store.GetJourney(r.Context(), req.TargetJourneyID)
	if err != nil {
		errResp(w, 404, "not_found", "target journey not found")
		return
	}

	// Merge sample IDs from sources into target
	seen := make(map[string]bool)
	for _, sid := range target.SampleIDs {
		seen[sid] = true
	}
	for _, srcID := range req.SourceJourneyIDs {
		src, err := h.Store.GetJourney(r.Context(), srcID)
		if err != nil {
			continue
		}
		for _, sid := range src.SampleIDs {
			if !seen[sid] {
				// Validate compatibility
				target.SampleIDs = append(target.SampleIDs, sid)
				seen[sid] = true
			}
		}
		src.Status = "merged"
		h.Store.UpdateJourneyStatus(r.Context(), src.ID, "merged")
	}

	target.PlanVersion++
	h.Store.UpdateJourneyPlanVersion(r.Context(), target.ID, target.PlanVersion)

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"targetJourneyId":  target.ID,
			"planVersion":      target.PlanVersion,
			"sourceJourneyIds": req.SourceJourneyIDs,
		},
	})
}

// EditActivePlan
func (h *Handler) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID          string                   `json:"journeyId"`
		ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
		ChangeType         string                   `json:"changeType"`
		Changes            []map[string]interface{} `json:"changes"`
