// CreateLocation
func (h *Handler) CreateLocation(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name            string                         `json:"name"`
		Coordinate      models.Coordinate              `json:"coordinate"`
		CoverageKm      *float64                       `json:"coverageKm"`
		HandlingMinutes *int                           `json:"handlingMinutes"`
		Active          *bool                          `json:"active"`
		Functions       models.LocationFunctionStates  `json:"functions"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	loc := &models.Location{
		ID:         uuid.New().String(),
		Name:       req.Name,
		Coordinate: req.Coordinate,
		Functions:  req.Functions,
	}
	if req.CoverageKm != nil {
		loc.CoverageKm = *req.CoverageKm
	} else {
		loc.CoverageKm = 5.0
	}
	if req.HandlingMinutes != nil {
		loc.HandlingMinutes = *req.HandlingMinutes
	}
	if req.Active != nil {
		loc.Active = *req.Active
	} else {
		loc.Active = true
	}

	if err := h.Store.CreateLocation(r.Context(), loc); err != nil {
		errResp(w, 409, "idempotency_conflict", "location creation failed")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "location.created", "location", loc.ID, true, "")
	respond(w, 201, map[string]interface{}{"data": loc})
}

// UpdateLocation
func (h *Handler) UpdateLocation(w http.ResponseWriter, r *http.Request) {
	var req struct {
		LocationID      string                         `json:"locationId"`
		Name            string                         `json:"name"`
		Coordinate      models.Coordinate              `json:"coordinate"`
		CoverageKm      *float64                       `json:"coverageKm"`
		HandlingMinutes *int                           `json:"handlingMinutes"`
		Functions       models.LocationFunctionStates  `json:"functions"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	loc, err := h.Store.GetLocation(r.Context(), req.LocationID)
	if err != nil {
		errResp(w, 404, "not_found", "location not found")
		return
	}

	if req.Name != "" {
		loc.Name = req.Name
	}
	if req.Coordinate.Latitude != 0 || req.Coordinate.Longitude != 0 {
		loc.Coordinate = req.Coordinate
	}
	if req.CoverageKm != nil {
		loc.CoverageKm = *req.CoverageKm
	}
	if req.HandlingMinutes != nil {
		loc.HandlingMinutes = *req.HandlingMinutes
	}
	loc.Functions = req.Functions

	if err := h.Store.UpdateLocation(r.Context(), loc); err != nil {
		errResp(w, 500, "internal_error", "update failed")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "location.updated", "location", loc.ID, true, "")
	respond(w, 201, map[string]interface{}{"data": loc})
}

// SetLocationStatus
func (h *Handler) SetLocationStatus(w http.ResponseWriter, r *http.Request) {
	var req struct {
		LocationID string `json:"locationId"`
		Active     bool   `json:"active"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	if err := h.Store.SetLocationStatus(r.Context(), req.LocationID, req.Active); err != nil {
		errResp(w, 404, "not_found", "location not found")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "location.status_changed", "location", req.LocationID, true, "")
	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"locationId": req.LocationID,
			"active":     req.Active,
		},
	})
}

// SetLocationFunctionStatus
func (h *Handler) SetLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	var req struct {
		LocationID string `json:"locationId"`
		Function   string `json:"function"`
		Active     bool   `json:"active"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	if err := h.Store.SetLocationFunctionStatus(r.Context(), req.LocationID, req.Function, req.Active); err != nil {
		errResp(w, 404, "not_found", "location not found")
		return
	}

	loc, _ := h.Store.GetLocation(r.Context(), req.LocationID)
