	})
}

// SplitJourney
func (h *Handler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	var req struct {
		JourneyID          string   `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		SampleIDs          []string `json:"sampleIds"`
		IdempotencyKey     string   `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	// Simple implementation: create a new journey with the specified samples
	newJourney := &models.Journey{
		ID:                    uuid.New().String(),
		ParentJourneyID:       &req.JourneyID,
		PlanVersion:           1,
		RouteMode:             "direct",
		Status:                "planned",
		SampleIDs:             req.SampleIDs,
		Valid:                 true,
		CollectionAssignmentIDs: []string{},
		NodeAssignmentIDs:       []string{},
		LaboratoryAssignmentIDs: []string{},
	}

	if err := h.Store.CreateJourney(r.Context(), newJourney); err != nil {
		errResp(w, 500, "internal_error", "split journey failed")
		return
	}

	origJourney, _ := h.Store.GetJourney(r.Context(), req.JourneyID)
	if origJourney != nil {
		// Remove split samples from original
		splitID := newJourney.ID
		origJourney.SplitJourney = &splitID
		h.Store.UpdateJourneyStatus(r.Context(), origJourney.ID, "split")
	}

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"journey":      newJourney,
			"splitJourney": newJourney,
		},
	})
}

// MergeJourneys
func (h *Handler) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	var req struct {
		TargetJourneyID    string   `json:"targetJourneyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		SourceJourneyIDs   []string `json:"sourceJourneyIds"`
		IdempotencyKey     string   `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	target, err := h.Store.GetJourney(r.Context(), req.TargetJourneyID)
	if err != nil {
		errResp(w, 404, "not_found", "target journey not found")
		return
	}

	// Merge sample IDs from sources into target
	seen := make(map[string]bool)
	for _, sid := range target.SampleIDs {
		seen[sid] = true
	}
	for _, srcID := range req.SourceJourneyIDs {
		src, err := h.Store.GetJourney(r.Context(), srcID)
		if err != nil {
			continue
		}
		for _, sid := range src.SampleIDs {
			if !seen[sid] {
				// Validate compatibility
				target.SampleIDs = append(target.SampleIDs, sid)
				seen[sid] = true
			}
		}
		src.Status = "merged"
		h.Store.UpdateJourneyStatus(r.Context(), src.ID, "merged")
	}

	target.PlanVersion++
	h.Store.UpdateJourneyPlanVersion(r.Context(), target.ID, target.PlanVersion)

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"targetJourneyId":  target.ID,
			"planVersion":      target.PlanVersion,
			"sourceJourneyIds": req.SourceJourneyIDs,
		},
	})
}

