			},
			"serverTime":       time.Now().UTC(),
			"requesterSamples": requesterSamples,
			"operations":       ops,
		},
	})
}

func (h *Handler) buildOperationsState(ctx context.Context) interface{} {
	// Simplified version of operations state for bootstrap
	return models.OperationsState{
