// ConfirmHandoff
func (h *Handler) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	var req struct {
		HandoffID        string    `json:"handoffId"`
		ConfirmationSide string    `json:"confirmationSide"`
		ConfirmedAt      time.Time `json:"confirmedAt"`
		IdempotencyKey   string    `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	ho, err := h.Store.GetHandoff(r.Context(), req.HandoffID)
	if err != nil {
		errResp(w, 404, "not_found", "handoff not found")
		return
	}

	if req.ConfirmationSide == "sender" {
		ho.SenderConfirmed = true
	} else if req.ConfirmationSide == "receiver" {
		ho.ReceiverConfirmed = true
	} else {
		errResp(w, 400, "invalid_json", "confirmationSide must be sender or receiver")
		return
	}

	if ho.SenderConfirmed && ho.ReceiverConfirmed {
		ho.Status = "completed"
		ho.CurrentHolderID = ho.ReceiverID
		ho.CompletedAt = &req.ConfirmedAt

		// Update sample holder
		sm, _ := h.Store.GetSample(r.Context(), ho.SampleID)
		if sm != nil {
			sm.CurrentHolderID = &ho.ReceiverID
			sm.PendingHandoffID = nil
			h.Store.UpdateSample(r.Context(), sm)
		}
	}

	if err := h.Store.UpdateHandoff(r.Context(), ho); err != nil {
		errResp(w, 500, "internal_error", "handoff update failed")
		return
	}

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"handoffId":         ho.HandoffID,
			"status":            ho.Status,
			"senderConfirmed":   ho.SenderConfirmed,
			"receiverConfirmed": ho.ReceiverConfirmed,
			"currentHolderId":   ho.CurrentHolderID,
		},
	})
}

// ConfirmLaboratoryReceipt
func (h *Handler) ConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID       string    `json:"sampleId"`
		LaboratoryID   string    `json:"laboratoryId"`
		ReceivedAt     time.Time `json:"receivedAt"`
		IdempotencyKey string    `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	userID := middleware.GetUserID(r.Context())

	sm, err := h.Store.GetSample(r.Context(), req.SampleID)
	if err != nil {
		errResp(w, 404, "not_found", "sample not found")
		return
	}

	sm.Status = "received"
	sm.State = "received"
	sm.ReceivedLaboratoryID = &req.LaboratoryID
	sm.CurrentHolderID = &userID
	h.Store.UpdateSample(r.Context(), sm)

	h.Store.AddSampleTimeline(r.Context(), models.TimelineEntry{
		EventID:    uuid.New().String(),
		Action:     "laboratory_received",
		ActorID:    userID,
		Role:       middleware.GetRole(r.Context()),
		EntityType: "sample",
		EntityID:   sm.ID,
		Success:    true,
		OccurredAt: req.ReceivedAt,
		Details:    "Sample received at laboratory",
	})

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"sampleId":     sm.ID,
			"laboratoryId": req.LaboratoryID,
			"status":       "received",
			"receivedAt":   req.ReceivedAt,
		},
	})
}

// RecordHandlingCheckpoint
func (h *Handler) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID             string    `json:"sampleId"`
		AssignmentID         string    `json:"assignmentId"`
		LocationID           string    `json:"locationId"`
		ContainerType        string    `json:"containerType"`
		ObservedTemperatureC float64   `json:"observedTemperatureC"`
		RecordedAt           time.Time `json:"recordedAt"`
		IdempotencyKey       string    `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	cpID, err := h.Store.RecordHandlingCheckpoint(r.Context(), req.SampleID, req.AssignmentID, req.LocationID, req.ContainerType, req.ObservedTemperatureC, req.RecordedAt)
	if err != nil {
		errResp(w, 500, "internal_error", "checkpoint recording failed")
		return
	}

	// Check compliance
	sm, _ := h.Store.GetSample(r.Context(), req.SampleID)
	compliant := true
	if sm != nil {
		if sm.TemperatureMinC != nil && req.ObservedTemperatureC < *sm.TemperatureMinC {
			compliant = false
		}
		if sm.TemperatureMaxC != nil && req.ObservedTemperatureC > *sm.TemperatureMaxC {
			compliant = false
		}
		if !compliant {
			exc := "handling_noncompliant"
			sm.Exception = &exc
			h.Store.UpdateSample(r.Context(), sm)
		}
	}

	sampleStatus := "in_transit"
	if sm != nil {
		sampleStatus = sm.Status
	}

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"checkpointId":  cpID,
			"sampleId":      req.SampleID,
			"compliant":     compliant,
			"sampleStatus":  sampleStatus,
		},
	})
}

