package handlers

import (
	"context"
	"encoding/json"
	"log"
	"net/http"
	"time"

	"lab-sample-system/internal/auth"
	"lab-sample-system/internal/middleware"
	"lab-sample-system/internal/models"
	"lab-sample-system/internal/service"
	"lab-sample-system/internal/store"

	"github.com/google/uuid"
)

type Handler struct {
	Store   *store.Store
	Service *service.Service
}

func New(s *store.Store, svc *service.Service) *Handler {
	return &Handler{Store: s, Service: svc}
}

func respond(w http.ResponseWriter, code int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(v)
}

func errResp(w http.ResponseWriter, code int, errCode, msg string) {
	respond(w, code, map[string]string{"error": msg, "code": errCode})
}

func getReqBody(r *http.Request, v interface{}) error {
	defer r.Body.Close()
	return json.NewDecoder(r.Body).Decode(v)
}

func (h *Handler) writeAudit(userID, role, action, entityType, entityID string, success bool, details string) {
	e := models.AuditEntry{
		AuditID:    uuid.New().String(),
		ActorID:    userID,
		Role:       role,
		ActorRole:  role,
		Action:     action,
		EntityType: entityType,
		EntityID:   entityID,
		Success:    success,
		OccurredAt: time.Now().UTC(),
		Details:    details,
	}
	if err := h.Store.WriteAudit(r.Context(), e); err != nil {
		log.Printf("audit write error: %v", err)
	}
}

func addTimeline(ctx context.Context, store *store.Store, sampleID, userID, role, action, details string, success bool) {
	now := time.Now().UTC()
	te := models.TimelineEntry{
		EventID:    uuid.New().String(),
		Action:     action,
		ActorID:    userID,
		Role:       role,
		EntityType: "sample",
		EntityID:   sampleID,
		Success:    success,
		OccurredAt: now,
		Details:    details,
	}
	store.AddSampleTimeline(ctx, te)
}

// SystemReadiness
func (h *Handler) SystemReadiness(w http.ResponseWriter, r *http.Request) {
	err := h.Store.DB().PingContext(r.Context())
	if err != nil {
		respond(w, http.StatusServiceUnavailable, map[string]string{"status": "not_ready"})
		return
	}
	if _, err := h.Store.Redis().Ping(r.Context()).Result(); err != nil {
		respond(w, http.StatusServiceUnavailable, map[string]string{"status": "not_ready"})
		return
	}
	respond(w, http.StatusOK, map[string]string{"status": "ready"})
}

// AuthenticateUser
func (h *Handler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}
	if req.Username == "" || req.Password == "" {
		errResp(w, 400, "invalid_json", "username and password required")
		return
	}

	user, err := h.Store.GetUserByUsername(r.Context(), req.Username)
	if err != nil {
		errResp(w, 401, "unauthorized", "invalid credentials")
		return
	}
	if !user.Active {
		errResp(w, 401, "unauthorized", "account deactivated")
		return
	}
	if !auth.CheckPassword(req.Password, user.PasswordHash) {
		errResp(w, 401, "unauthorized", "invalid credentials")
		return
	}

	token, err := auth.GenerateToken()
	if err != nil {
		errResp(w, 500, "internal_error", "failed to create session")
		return
	}

	activeRole := ""
	if len(user.Roles) > 0 {
		activeRole = user.Roles[0]
	}

	if err := h.Store.CreateSession(r.Context(), token, user.ID, activeRole, 24*time.Hour); err != nil {
		errResp(w, 500, "internal_error", "failed to create session")
		return
	}

	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"sessionToken": token,
			"userId":       user.ID,
			"roles":        user.Roles,
			"activeRole":   activeRole,
		},
	})
}

// SelectActiveRole
func (h *Handler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	userID := middleware.GetUserID(r.Context())
	user, err := h.Store.GetUserByID(r.Context(), userID)
	if err != nil {
		errResp(w, 404, "not_found", "user not found")
		return
	}

	valid := false
	for _, rl := range user.Roles {
		if rl == req.Role {
			valid = true
			break
		}
	}
	if !valid {
		errResp(w, 400, "invalid_json", "user does not have that role")
		return
	}

	// Extract token from auth header
	authHdr := r.Header.Get("Authorization")
	token := ""
	if len(authHdr) > 7 && authHdr[:7] == "Bearer " {
		token = authHdr[7:]
	}

	if token != "" {
		h.Store.UpdateSessionRole(r.Context(), token, req.Role)
	}

	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"activeRole": req.Role,
			"roles":      user.Roles,
		},
	})
}

// CreateUser
func (h *Handler) CreateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username           string                 `json:"username"`
		InitialPassword    string                 `json:"initialPassword"`
		Email              string                 `json:"email"`
		FullName           string                 `json:"fullName"`
		Phone              string                 `json:"phone"`
		Roles              []string               `json:"roles"`
		Qualifications     []models.Qualification `json:"qualifications"`
		Certifications     []models.Certification `json:"certifications"`
		Active             *bool                  `json:"active"`
		AssignedLocationID *string                `json:"assignedLocationId"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	hash, err := auth.HashPassword(req.InitialPassword)
	if err != nil {
		errResp(w, 500, "internal_error", "password hashing failed")
		return
	}

	active := true
	if req.Active != nil {
		active = *req.Active
	}

	user := &models.User{
		ID:                 uuid.New().String(),
		Username:           req.Username,
		PasswordHash:       hash,
		Email:              req.Email,
		FullName:           req.FullName,
		Phone:              req.Phone,
		Roles:              req.Roles,
		Qualifications:     req.Qualifications,
		Certifications:     req.Certifications,
		Active:             active,
		AssignedLocationID: req.AssignedLocationID,
	}

	if err := h.Store.CreateUser(r.Context(), user); err != nil {
		errResp(w, 409, "idempotency_conflict", "username already exists")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "user.created", "user", user.ID, true, "")

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":         user.ID,
			"username":       user.Username,
			"email":          user.Email,
			"fullName":       user.FullName,
			"phone":          user.Phone,
			"roles":          user.Roles,
			"qualifications": user.Qualifications,
			"certifications": user.Certifications,
			"active":         user.Active,
		},
	})
}

// ReadUser
func (h *Handler) ReadUser(w http.ResponseWriter, r *http.Request) {
	userID := r.PathValue("userId")
	user, err := h.Store.GetUserByID(r.Context(), userID)
	if err != nil {
		errResp(w, 404, "not_found", "user not found")
		return
	}
	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":         user.ID,
			"username":       user.Username,
			"email":          user.Email,
			"fullName":       user.FullName,
			"phone":          user.Phone,
			"roles":          user.Roles,
			"qualifications": user.Qualifications,
			"certifications": user.Certifications,
			"active":         user.Active,
		},
	})
}

// UpdateUserAccess
func (h *Handler) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	var req struct {
		UserID             string                 `json:"userId"`
		Roles              []string               `json:"roles"`
		Qualifications     []models.Qualification `json:"qualifications"`
		Certifications     []models.Certification `json:"certifications"`
		Active             *bool                  `json:"active"`
		AssignedLocationID *string                `json:"assignedLocationId"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	active := true
	if req.Active != nil {
		active = *req.Active
	}

	if err := h.Store.UpdateUserAccess(r.Context(), req.UserID, req.Roles, req.Qualifications, req.Certifications, active, req.AssignedLocationID); err != nil {
		errResp(w, 404, "not_found", "user not found")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "user.updated", "user", req.UserID, true, "")
	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"userId":         req.UserID,
			"roles":          req.Roles,
			"qualifications": req.Qualifications,
			"certifications": req.Certifications,
			"active":         active,
		},
	})
}

// CreateLocation
func (h *Handler) CreateLocation(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name            string                         `json:"name"`
		Coordinate      models.Coordinate              `json:"coordinate"`
		CoverageKm      *float64                       `json:"coverageKm"`
		HandlingMinutes *int                           `json:"handlingMinutes"`
		Active          *bool                          `json:"active"`
		Functions       models.LocationFunctionStates  `json:"functions"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	loc := &models.Location{
		ID:         uuid.New().String(),
		Name:       req.Name,
		Coordinate: req.Coordinate,
		Functions:  req.Functions,
	}
	if req.CoverageKm != nil {
		loc.CoverageKm = *req.CoverageKm
	} else {
		loc.CoverageKm = 5.0
	}
	if req.HandlingMinutes != nil {
		loc.HandlingMinutes = *req.HandlingMinutes
	}
	if req.Active != nil {
		loc.Active = *req.Active
	} else {
		loc.Active = true
	}

	if err := h.Store.CreateLocation(r.Context(), loc); err != nil {
		errResp(w, 409, "idempotency_conflict", "location creation failed")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "location.created", "location", loc.ID, true, "")
	respond(w, 201, map[string]interface{}{"data": loc})
}

// UpdateLocation
func (h *Handler) UpdateLocation(w http.ResponseWriter, r *http.Request) {
	var req struct {
		LocationID      string                         `json:"locationId"`
		Name            string                         `json:"name"`
		Coordinate      models.Coordinate              `json:"coordinate"`
		CoverageKm      *float64                       `json:"coverageKm"`
		HandlingMinutes *int                           `json:"handlingMinutes"`
		Functions       models.LocationFunctionStates  `json:"functions"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	loc, err := h.Store.GetLocation(r.Context(), req.LocationID)
	if err != nil {
		errResp(w, 404, "not_found", "location not found")
		return
	}

	if req.Name != "" {
		loc.Name = req.Name
	}
	if req.Coordinate.Latitude != 0 || req.Coordinate.Longitude != 0 {
		loc.Coordinate = req.Coordinate
	}
	if req.CoverageKm != nil {
		loc.CoverageKm = *req.CoverageKm
	}
	if req.HandlingMinutes != nil {
		loc.HandlingMinutes = *req.HandlingMinutes
	}
	loc.Functions = req.Functions

	if err := h.Store.UpdateLocation(r.Context(), loc); err != nil {
		errResp(w, 500, "internal_error", "update failed")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "location.updated", "location", loc.ID, true, "")
	respond(w, 201, map[string]interface{}{"data": loc})
}

// SetLocationStatus
func (h *Handler) SetLocationStatus(w http.ResponseWriter, r *http.Request) {
	var req struct {
		LocationID string `json:"locationId"`
		Active     bool   `json:"active"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	if err := h.Store.SetLocationStatus(r.Context(), req.LocationID, req.Active); err != nil {
		errResp(w, 404, "not_found", "location not found")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "location.status_changed", "location", req.LocationID, true, "")
	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"locationId": req.LocationID,
			"active":     req.Active,
		},
	})
}

// SetLocationFunctionStatus
func (h *Handler) SetLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	var req struct {
		LocationID string `json:"locationId"`
		Function   string `json:"function"`
		Active     bool   `json:"active"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	if err := h.Store.SetLocationFunctionStatus(r.Context(), req.LocationID, req.Function, req.Active); err != nil {
		errResp(w, 404, "not_found", "location not found")
		return
	}

	loc, _ := h.Store.GetLocation(r.Context(), req.LocationID)
	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "location.function_status_changed", "location", req.LocationID, true, "")

	funcs := models.LocationFunctionStates{}
	if loc != nil {
		funcs = loc.Functions
	}

	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"locationId": req.LocationID,
			"function":   req.Function,
			"active":     req.Active,
			"functions":  funcs,
		},
	})
}

// ConfigureCapacity
func (h *Handler) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	var req struct {
		ResourceID         string `json:"resourceId"`
		CapacityUnits      *int   `json:"capacityUnits"`
		CooledCapacityUnits *int  `json:"cooledCapacityUnits"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	units := 0
	cooled := 0
	if req.CapacityUnits != nil {
		units = *req.CapacityUnits
	}
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}

	if err := h.Store.SetLocationCapacity(r.Context(), req.ResourceID, units, cooled); err != nil {
		errResp(w, 500, "internal_error", "capacity update failed")
		return
	}

	h.writeAudit(middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "capacity.configured", "capacity", req.ResourceID, true, "")
	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"resourceId":         req.ResourceID,
			"capacityUnits":      units,
			"cooledCapacityUnits": cooled,
		},
	})
}

// CreateConnection
func (h *Handler) CreateConnection(w http.ResponseWriter, r *http.Request) {
	var req struct {
