package events

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"lab-sample-system/internal/store"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type Hub struct {
	store  *store.Store
	mu     sync.RWMutex
	conns  map[*websocket.Conn]connInfo
}

type connInfo struct {
	userID string
	role   string
	since  int64
}

func NewHub(s *store.Store) *Hub {
	return &Hub{
		store: s,
		conns: make(map[*websocket.Conn]connInfo),
	}
}

func (h *Hub) HandleWebSocket(w http.ResponseWriter, r *http.Request) {
	// Extract bearer [REDACTED] from subprotocol
	proto := r.Header.Get("Sec-WebSocket-Protocol")
	if proto == "" {
		http.Error(w, "missing protocol", http.StatusUnauthorized)
		return
	}

	// Parse bearer [REDACTED]: base64url-encoded "bearer.<token>"
	token := ""
	parts := strings.Split(proto, ",")
	for _, p := range parts {
		p = strings.TrimSpace(p)
		if len(p) > 7 {
			decoded, err := base64.RawURLEncoding.DecodeString(p)
			if err == nil {
				s := string(decoded)
				if strings.HasPrefix(s, "bearer.") {
					token = s[len("bearer."):]
				}
			}
		}
	}

	if token == "" {
		http.Error(w, "invalid token", http.StatusUnauthorized)
		return
	}

	userID, role, err := h.store.GetSession(r.Context(), token)
	if err != nil {
		http.Error(w, "invalid session", http.StatusUnauthorized)
		return
	}

	// Parse since parameter
	sinceStr := r.URL.Query().Get("since")
	var since int64
	if sinceStr != "" {
		since, _ = strconv.ParseInt(sinceStr, 10, 64)
	}

	conn, err := upgrader.Upgrade(w, r, http.Header{
		"Sec-WebSocket-Protocol": {proto},
	})
	if err != nil {
		log.Printf("WebSocket upgrade error: %v", err)
		return
	}

	info := connInfo{userID: userID, role: role, since: since}
	h.mu.Lock()
	h.conns[conn] = info
	h.mu.Unlock()

	// Send any events since the cursor
	if since > 0 {
		events, newCursor, _ := h.store.GetRealtimeEventsSince(r.Context(), since)
		if len(events) > 0 {
			msg, _ := json.Marshal(map[string]interface{}{
				"events": events,
				"cursor": fmt.Sprintf("%d", newCursor),
			})
			conn.WriteMessage(websocket.TextMessage, msg)
		}
	}

	go h.readLoop(conn)

	// Subscribe to Redis pub/sub for live events
	pubsub := h.store.Redis().Subscribe(r.Context(), "events")
	defer pubsub.Close()

	ch := pubsub.Channel()
	for {
		select {
		case msg := <-ch:
			h.mu.RLock()
			info, ok := h.conns[conn]
			h.mu.RUnlock()
			if !ok {
				return
			}

			var event struct {
				ID   int64  `json:"id"`
				Type string `json:"type"`
			}
			json.Unmarshal([]byte(msg.Payload), &event)

			// Send event if role matches
			conn.WriteMessage(websocket.TextMessage, []byte(msg.Payload))
			info.since = event.ID
			h.mu.Lock()
			h.conns[conn] = info
			h.mu.Unlock()
		}
	}
}

func (h *Hub) readLoop(conn *websocket.Conn) {
	defer func() {
		h.mu.Lock()
		delete(h.conns, conn)
		h.mu.Unlock()
		conn.Close()
	}()

	conn.SetReadDeadline(time.Now().Add(60 * time.Second))
	conn.SetPongHandler(func(string) error {
		conn.SetReadDeadline(time.Now().Add(60 * time.Second))
		return nil
	})

	for {
		_, _, err := conn.ReadMessage()
		if err != nil {
			break
		}
	}
}

