func (s *Store) SaveServiceabilitySnapshot(ctx context.Context, version string, computedAt time.Time, revision string, count int, regions []models.ServiceabilityRegion) error {
	_, err := s.db.ExecContext(ctx, `INSERT INTO serviceability_snapshot (version, status, computed_at, network_revision, active_collection_point_count) VALUES ($1,'computed',$2,$3,$4) ON CONFLICT (version) DO NOTHING`,
		version, computedAt, revision, count)
	if err != nil {
		return err
	}
	for _, r := range regions {
		s.db.ExecContext(ctx, `INSERT INTO serviceability_regions (snapshot_version, location_id, name, latitude, longitude, coverage_km) VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING`,
			version, r.LocationID, r.Name, r.Latitude, r.Longitude, r.CoverageKm)
	}
	return nil
}

func (s *Store) GetLatestServiceabilitySnapshot(ctx context.Context) (*models.ServiceabilitySnapshot, error) {
	sn := &models.ServiceabilitySnapshot{}
	err := s.db.QueryRowContext(ctx, `SELECT version, status, computed_at, network_revision, active_collection_point_count FROM serviceability_snapshot ORDER BY computed_at DESC LIMIT 1`).Scan(
		&sn.Version, &sn.Status, &sn.ComputedAt, &sn.NetworkRevision, &sn.ActiveCollectionPointCount)
	if err != nil {
		return nil, err
	}
	rows, err := s.db.QueryContext(ctx, `SELECT location_id, name, latitude, longitude, coverage_km FROM serviceability_regions WHERE snapshot_version=$1`, sn.Version)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var r models.ServiceabilityRegion
			rows.Scan(&r.LocationID, &r.Name, &r.Latitude, &r.Longitude, &r.CoverageKm)
			sn.Regions = append(sn.Regions, r)
		}
	}
	return sn, nil
}

