	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var cons []models.Connection
	for rows.Next() {
		var c models.Connection
		if err := rows.Scan(&c.ID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active); err != nil {
			return nil, err
		}
		cons = append(cons, c)
	}
	return cons, nil
}

func (s *Store) SetConnectionStatus(ctx context.Context, id string, active bool) error {
	_, err := s.db.ExecContext(ctx, `UPDATE connections SET active=$1 WHERE id=$2`, active, id)
	return err
}

func (s *Store) GetConnectionCapacity(ctx context.Context, connID string) (models.Capacity, error) {
	var cap models.Capacity
	var capUnits, cooledCap, reserved, cooledReserved int
	err := s.db.QueryRowContext(ctx, `
		SELECT COALESCE(capacity_units,0), COALESCE(cooled_capacity_units,0), COALESCE(reserved_units,0), COALESCE(cooled_reserved_units,0)
		FROM connections WHERE id=$1`, connID).Scan(&capUnits, &cooledCap, &reserved, &cooledReserved)
	if err != nil {
		return cap, err
	}
	cap.CapacityUnits = capUnits
	cap.CooledCapacityUnits = cooledCap
	cap.ReservedUnits = reserved
	cap.CooledReservedUnits = cooledReserved
	cap.AvailableUnits = capUnits - reserved
	cap.CooledAvailableUnits = cooledCap - cooledReserved
	return cap, nil
}

