		&h.ID, &h.HandoffID, &h.SampleID, &h.SenderID, &h.ReceiverID, &h.CurrentHolderID,
		&h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.FromAssignmentID, &h.ToAssignmentID,
		&h.InitiatedAt, &completedAt)
	if err != nil {
		return nil, err
	}
	if completedAt.Valid {
		h.CompletedAt = &completedAt.Time
	}
	return h, nil
}

