func (s *Store) GetSample(ctx context.Context, id string) (*models.Sample, error) {
	sm := &models.Sample{}
	var activeJourneyID, targetLabID, currentHolderID, receivedLabID, exception, originNodeID sql.NullString
	var latestLat, latestLon sql.NullFloat64
	var locationRecordedAt sql.NullTime
	err := s.db.QueryRowContext(ctx, `
		SELECT id, request_id, requester_id, status, sealed, origin_lat, origin_lon, origin_type, origin_node_id,
			requested_at, delivery_deadline, sample_type_id, container_type, temperature_min_c, temperature_max_c,
			incompatible_sample_types, serviceability, serviceability_reason, state, active_journey_id, target_laboratory_id,
			current_holder_id, received_laboratory_id, exception, latest_location_lat, latest_location_lon,
			location_recorded_at, location_stale, earliest_collection_at, latest_collection_at
		FROM samples WHERE id = $1`, id).Scan(
		&sm.ID, &sm.RequestID, &sm.RequesterID, &sm.Status, &sm.Sealed,
		&sm.Origin.Latitude, &sm.Origin.Longitude, &sm.OriginType, &originNodeID,
		&sm.RequestedAt, &sm.DeliveryDeadline, &sm.SampleTypeID, &sm.ContainerType,
		&sm.TemperatureMinC, &sm.TemperatureMaxC, pq.Array(&sm.IncompatibleSampleTypes),
		&sm.Serviceability, &sm.ServiceabilityReason, &sm.State, &activeJourneyID, &targetLabID,
		&currentHolderID, &receivedLabID, &exception, &latestLat, &latestLon,
		&locationRecordedAt, &sm.LocationStale, &sm.EarliestCollectionAt, &sm.LatestCollectionAt)
	if err != nil {
		return nil, err
	}
	if activeJourneyID.Valid {
		sm.ActiveJourneyID = &activeJourneyID.String
	}
	if targetLabID.Valid {
		sm.TargetLaboratoryID = &targetLabID.String
	}
	if currentHolderID.Valid {
		sm.CurrentHolderID = &currentHolderID.String
	}
	if receivedLabID.Valid {
		sm.ReceivedLaboratoryID = &receivedLabID.String
	}
	if exception.Valid {
		sm.Exception = &exception.String
	}
	if originNodeID.Valid {
		sm.OriginNodeID = &originNodeID.String
	}
	if latestLat.Valid && latestLon.Valid {
		sm.LatestLocation = &models.Coordinate{Latitude: latestLat.Float64, Longitude: latestLon.Float64}
	}
	if locationRecordedAt.Valid {
		sm.LocationRecordedAt = &locationRecordedAt.Time
	}
	// Load active assignment IDs
	rows, err := s.db.QueryContext(ctx, `SELECT id FROM assignments WHERE sample_id=$1 AND status NOT IN ('completed','cancelled','declined')`, id)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var aid string
			rows.Scan(&aid)
			sm.ActiveAssignmentIDs = append(sm.ActiveAssignmentIDs, aid)
		}
	}
	// Load timeline
	sm.Timeline, _ = s.GetSampleTimeline(ctx, id)
	// Load completed legs
	sm.CompletedLegIDs, _ = s.GetSampleCompletedLegs(ctx, id)
	// Load replacement plans
	sm.ActiveReplacementPlanIDs, _ = s.GetSampleReplacementPlans(ctx, id)
	return sm, nil
}

func (s *Store) UpdateSample(ctx context.Context, sm *models.Sample) error {
	var latestLat, latestLon interface{}
	if sm.LatestLocation != nil {
		latestLat, latestLon = sm.LatestLocation.Latitude, sm.LatestLocation.Longitude
	}
	_, err := s.db.ExecContext(ctx, `
		UPDATE samples SET status=$1, sealed=$2, state=$3, active_journey_id=$4, target_laboratory_id=$5,
			current_holder_id=$6, received_laboratory_id=$7, exception=$8,
			latest_location_lat=$9, latest_location_lon=$10, location_recorded_at=$11, location_stale=$12,
			serviceability=$13, serviceability_reason=$14
		WHERE id=$15`,
		sm.Status, sm.Sealed, sm.State, sm.ActiveJourneyID, sm.TargetLaboratoryID,
		sm.CurrentHolderID, sm.ReceivedLaboratoryID, sm.Exception,
		latestLat, latestLon, sm.LocationRecordedAt, sm.LocationStale,
		sm.Serviceability, sm.ServiceabilityReason, sm.ID)
	return err
}

