	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var locs []models.Location
	for rows.Next() {
		var l models.Location
		var funcs []byte
		if err := rows.Scan(&l.ID, &l.Name, &l.Coordinate.Latitude, &l.Coordinate.Longitude, &l.CoverageKm, &l.HandlingMinutes, &l.Active, &funcs); err != nil {
			return nil, err
