function RoleWorkView({ work }: { work: any }) {
  const renderItems = (items: any[], fallback: string) => {
    if (!items || items.length === 0) return <p style={{fontSize:13,color:'#888'}}>{fallback}</p>
    return items.map((item: any, i: number) => (
      <div key={i} className="card" style={{padding:12,marginBottom:8}}>
        <div className="info-row">
          <span className="badge badge-pending">{item.kind || 'item'}</span>
          <span className="badge" style={{background: item.status==='completed'?'#55efc4':'#74b9ff'}}>{item.status}</span>
