          {item.journeyId && <span style={{fontSize:12,color:'#888'}}>Journey: {item.journeyId?.slice(0,8)}...</span>}
          {item.assignmentId && <span style={{fontSize:12,color:'#888'}}>Assignment: {item.assignmentId?.slice(0,8)}...</span>}
