          {item.assignmentId && <span style={{fontSize:12,color:'#888'}}>Assignment: {item.assignmentId?.slice(0,8)}...</span>}
        </div>
        {item.history && item.history.length > 0 && (
          <div className="timeline" style={{marginTop:8}}>
            {item.history.slice(-3).map((e: any, j: number) => (
              <div key={j} className="tl-entry">
                <span>{e.action}</span>
                <div className="tl-time">{new Date(e.occurredAt).toLocaleString()}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    ))
  }

  return (
    <div>
      <div className="tabs" style={{marginBottom:8}}>
        <span className="tab active">Pending ({work.pending?.length||0})</span>
        <span className="tab">In Progress ({work.inProgress?.length||0})</span>
        <span className="tab">Completed ({work.completed?.length||0})</span>
      </div>
      <div><h4 style={{marginBottom:8,fontSize:14}}>Pending</h4>{renderItems(work.pending, 'No pending work')}</div>
    </div>
  )
}

function ServiceabilityCheck() {
  const [origin, setOrigin] = useState({ latitude: 0, longitude: 0 })
  const [originType, setOriginType] = useState('home')
  const [originNodeId, setOriginNodeId] = useState('')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [deadline, setDeadline] = useState('')
  const [earliestCol, setEarliestCol] = useState('')
  const [latestCol, setLatestCol] = useState('')
  const [result, setResult] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [sampleTypes, setSampleTypes] = useState<any[]>([])

  useEffect(() => {
    api('POST', '/read-serviceability-snapshot').then(r => {
      if (r.ok) setSampleTypes(r.data?.data?.regions || [])
    })
  }, [])

  const check = async () => {
    setLoading(true)
    const r = await api('POST', '/check-serviceability', {
      origin, originType, originNodeId: originNodeId || undefined,
      sampleTypeId, requestedAt: new Date().toISOString(),
      deliveryDeadline: new Date(deadline).toISOString(),
      earliestCollectionAt: new Date(earliestCol).toISOString(),
      latestCollectionAt: new Date(latestCol).toISOString(),
    })
    setResult(r.data)
    setLoading(false)
  }

  return (
    <div>
      <h3 style={{marginBottom:16}}>Serviceability Check (Dry Run)</h3>
      <div className="card">
        <div className="form-row">
          <div className="form-group"><label>Latitude</label><input type="number" step="any" value={origin.latitude} onChange={e => setOrigin({...origin, latitude: +e.target.value})} /></div>
          <div className="form-group"><label>Longitude</label><input type="number" step="any" value={origin.longitude} onChange={e => setOrigin({...origin, longitude: +e.target.value})} /></div>
        </div>
        <div className="form-group"><label>Origin Type</label><select value={originType} onChange={e => setOriginType(e.target.value)}><option value="home">Home</option><option value="clinic">Clinic</option><option value="node">Node</option></select></div>
        {originType === 'node' && <div className="form-group"><label>Origin Node ID</label><input value={originNodeId} onChange={e => setOriginNodeId(e.target.value)} /></div>}
        <div className="form-group"><label>Sample Type ID</label><input value={sampleTypeId} onChange={e => setSampleTypeId(e.target.value)} placeholder="UUID of sample type" /></div>
        <div className="form-row">
          <div className="form-group"><label>Earliest Collection</label><input type="datetime-local" value={earliestCol} onChange={e => setEarliestCol(e.target.value)} /></div>
          <div className="form-group"><label>Latest Collection</label><input type="datetime-local" value={latestCol} onChange={e => setLatestCol(e.target.value)} /></div>
        </div>
        <div className="form-group"><label>Delivery Deadline</label><input type="datetime-local" value={deadline} onChange={e => setDeadline(e.target.value)} /></div>
        <button className="btn btn-primary" onClick={check} disabled={loading}>{loading ? 'Checking...' : 'Check Serviceability'}</button>
      </div>
      {result && (
        <div className="card">
          <h3>Result</h3>
          <div className="info-row">
            <span className={`badge ${result.data?.serviceable ? 'badge-done' : 'badge-error'}`}>{result.data?.serviceable ? 'Serviceable' : 'Not Serviceable'}</span>
            {result.data?.reason && <span style={{fontSize:13}}>{result.data.reason}</span>}
            {result.data?.targetLaboratoryId && <span style={{fontSize:12,color:'#888'}}>Lab: {result.data.targetLaboratoryId?.slice(0,8)}...</span>}
          </div>
        </div>
      )}
      <p style={{fontSize:12,color:'#888',marginTop:8}}>This is a dry run — nothing is created or reserved.</p>
    </div>
  )
}

