              {(state.samples||[]).map((s: any, i: number) => (
                <tr key={i}>
                  <td>{s.sampleId?.slice(0,8)}...</td>
                  <td><span className="badge badge-active">{s.status}</span></td>
                  <td>{s.locationStale ? <span className="badge badge-error">Stale</span> : 'OK'}</td>
                </tr>
              ))}
            </tbody></table>
          </div>
        </div>
        <div className="card">
          <h3>Workers ({state.workers?.length || 0})</h3>
          <div style={{maxHeight:300,overflowY:'auto'}}>
            <table><thead><tr><th>ID</th><th>Status</th><th>Assignments</th></tr></thead><tbody>
              {(state.workers||[]).map((w: any, i: number) => (
