function RequesterSamples({ auth }: { auth: any }) {
  const [samples, setSamples] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [selected, setSelected] = useState<any>(null)

  useEffect(() => {
    api('POST', '/list-role-work', { role: 'requester', status: 'all' }).then(async r => {
      if (r.ok && r.data?.data) {
        const all = [...(r.data.data.pending||[]), ...(r.data.data.inProgress||[]), ...(r.data.data.completed||[])]
        setSamples(all)
        if (all.length > 0) {
          const s = await api('GET', `/read-sample-state/${all[0].sampleId}`)
          if (s.ok) setSelected(s.data?.data)
        }
      }
      setLoading(false)
    })
  }, [])

  const viewSample = async (sampleId: string) => {
    const s = await api('GET', `/read-sample-state/${sampleId}`)
    if (s.ok) setSelected(s.data?.data)
  }

  if (loading) return <p>Loading...</p>
  return (
    <div>
      <h3 style={{marginBottom:16}}>My Samples</h3>
      <div className="grid-2">
        <div>
          {samples.map(s => (
            <div key={s.sampleId} className="card" style={{padding:12,marginBottom:8,cursor:'pointer'}} onClick={() => viewSample(s.sampleId)}>
              <div className="info-row">
                <span className="badge badge-pending">Sample</span>
                <span style={{fontSize:13}}>{s.sampleId?.slice(0,8)}...</span>
                <span className={`badge ${s.status==='completed'?'badge-done':s.status==='in_progress'?'badge-active':'badge-pending'}`}>{s.status}</span>
                {s.locationStale && <span className="badge badge-error">Stale</span>}
              </div>
            </div>
          ))}
          {samples.length === 0 && <p style={{color:'#888'}}>No samples found</p>}
        </div>
        <div>
          {selected && <SampleDetail sample={selected} />}
        </div>
      </div>
    </div>
  )
}

