function LabIntake({ auth }: { auth: any }) {
  const [labId, setLabId] = useState('')
  const [sTypeId, setSTypeId] = useState('')
  const [accepts, setAccepts] = useState(true)
  const [capacityRes, setCapacityRes] = useState('')
  const [msg, setMsg] = useState('')

  const configureAcceptance = async () => {
    const r = await api('POST', '/configure-laboratory-acceptance', { laboratoryId: labId, sampleTypeId: sTypeId, accepts })
    setMsg(r.ok ? 'Configured' : r.data?.error || 'Failed')
  }

  const configureCapacity = async () => {
