    setLoading(true)
    const r = await api('POST', '/search-audit-trail', {
      query: query || undefined, actorId: undefined, entityType: entityType || undefined,
      entityId: undefined, action: undefined, role: undefined, success: undefined,
      fromTime: undefined, toTime: undefined, limit, offset: 0, order: 'newest_first'
    })
    if (r.ok) setEntries(r.data?.data)
    setLoading(false)
  }

  useEffect(() => { search() }, [])

  return (
    <div>
      <h3 style={{marginBottom:16}}>Audit Trail</h3>
      <div className="card">
