          <h3>Result</h3>
          <div className="info-row">
            <span className={`badge ${result.data?.serviceable ? 'badge-done' : 'badge-error'}`}>{result.data?.serviceable ? 'Serviceable' : 'Not Serviceable'}</span>
            {result.data?.reason && <span style={{fontSize:13}}>{result.data.reason}</span>}
            {result.data?.targetLaboratoryId && <span style={{fontSize:12,color:'#888'}}>Lab: {result.data.targetLaboratoryId?.slice(0,8)}...</span>}
          </div>
        </div>
      )}
