      earliestCollectionAt: new Date(earliestCol).toISOString(),
      latestCollectionAt: new Date(latestCol).toISOString(),
      containerType, temperatureMinC: null, temperatureMaxC: null,
      incompatibleSampleTypes: [], idempotencyKey: idKey,
    })
    setResult(r.data)
    setLoading(false)
  }

  return (
    <div>
      <h3 style={{marginBottom:16}}>Create Collection Request</h3>
      <div className="card">
        <div className="form-row">
          <div className="form-group"><label>Latitude</label><input type="number" step="any" value={origin.latitude} onChange={e => setOrigin({...origin, latitude: +e.target.value})} /></div>
          <div className="form-group"><label>Longitude</label><input type="number" step="any" value={origin.longitude} onChange={e => setOrigin({...origin, longitude: +e.target.value})} /></div>
        </div>
        <div className="form-group"><label>Origin Type</label><select value={originType} onChange={e => setOriginType(e.target.value)}><option value="home">Home</option><option value="clinic">Clinic</option><option value="node">Node</option></select></div>
        {originType === 'node' && <div className="form-group"><label>Origin Node ID</label><input value={originNodeId} onChange={e => setOriginNodeId(e.target.value)} /></div>}
        <div className="form-group"><label>Sample Type ID</label><input value={sampleTypeId} onChange={e => setSampleTypeId(e.target.value)} /></div>
        <div className="form-group"><label>Container Type</label><input value={containerType} onChange={e => setContainerType(e.target.value)} /></div>
        <div className="form-row">
          <div className="form-group"><label>Earliest Collection</label><input type="datetime-local" value={earliestCol} onChange={e => setEarliestCol(e.target.value)} /></div>
          <div className="form-group"><label>Latest Collection</label><input type="datetime-local" value={latestCol} onChange={e => setLatestCol(e.target.value)} /></div>
        </div>
        <div className="form-group"><label>Delivery Deadline</label><input type="datetime-local" value={deadline} onChange={e => setDeadline(e.target.value)} /></div>
        <button className="btn btn-primary" onClick={create} disabled={loading}>{loading ? 'Creating...' : 'Create Request'}</button>
      </div>
      {result && (
        <div className="card">
          <h3>Request Created</h3>
          <pre style={{fontSize:12, overflow:'auto'}}>{JSON.stringify(result.data, null, 2)}</pre>
        </div>
      )}
    </div>
  )
}

function RequesterSamples({ auth }: { auth: any }) {
