function MyWork({ auth }: { auth: any }) {
  const [work, setWork] = useState<any>(null)
  const [selectedItem, setSelectedItem] = useState<any>(null)

  useEffect(() => {
    api('POST', '/list-role-work', { role: auth.activeRole, status: 'all' }).then(r => {
      if (r.ok) setWork(r.data?.data || null)
    })
  }, [auth.activeRole])

  const acceptAssignment = async (assignmentId: string) => {
    const r = await api('POST', '/accept-assignment', { assignmentId, idempotencyKey: `acc-${assignmentId}-${Date.now()}` })
    if (r.ok) {
      api('POST', '/list-role-work', { role: auth.activeRole, status: 'all' }).then(r2 => { if (r2.ok) setWork(r2.data?.data) })
    } else {
      alert(r.data?.error || 'Failed to accept')
    }
  }

  const declineAssignment = async (assignmentId: string) => {
    const r = await api('POST', '/decline-assignment', { assignmentId, reason: 'unavailable', declinedAt: new Date().toISOString(), idempotencyKey: `dec-${assignmentId}-${Date.now()}` })
    if (r.ok) {
      api('POST', '/list-role-work', { role: auth.activeRole, status: 'all' }).then(r2 => { if (r2.ok) setWork(r2.data?.data) })
    }
  }

  const confirmHandoff = async (handoffId: string, side: string) => {
    const r = await api('POST', '/confirm-handoff', { handoffId, confirmationSide: side, confirmedAt: new Date().toISOString(), idempotencyKey: `ho-${handoffId}-${side}-${Date.now()}` })
    if (r.ok) alert('Handoff confirmed') else alert(r.data?.error)
  }

  const collectSample = async (sampleId: string, assignmentId: string) => {
    const r = await api('POST', '/collect-and-seal-sample', { sampleId, assignmentId, collectedAt: new Date().toISOString(), containerType: 'standard', observedTemperatureC: 22, idempotencyKey: `col-${sampleId}-${Date.now()}` })
    if (r.ok) alert('Sample collected and sealed') else alert(r.data?.error)
  }

  const initiateHandoff = async (sampleId: string, fromAssignmentId: string, toAssignmentId: string, receiverId: string) => {
    const r = await api('POST', '/initiate-handoff', { sampleId, fromAssignmentId, toAssignmentId, receiverId, initiatedAt: new Date().toISOString(), idempotencyKey: `init-ho-${sampleId}-${Date.now()}` })
    if (r.ok) alert('Handoff initiated') else alert(r.data?.error)
  }

  const confirmLabReceipt = async (sampleId: string, laboratoryId: string) => {
    const r = await api('POST', '/confirm-laboratory-receipt', { sampleId, laboratoryId, receivedAt: new Date().toISOString(), idempotencyKey: `rec-${sampleId}-${Date.now()}` })
    if (r.ok) alert('Laboratory receipt confirmed') else alert(r.data?.error)
  }

  const recordHandlingCheckpoint = async (sampleId: string, assignmentId: string) => {
    const r = await api('POST', '/record-handling-checkpoint', { sampleId, assignmentId, locationId: 'any', containerType: 'standard', observedTemperatureC: 22, recordedAt: new Date().toISOString(), idempotencyKey: `ck-${sampleId}-${Date.now()}` })
    if (r.ok) alert('Checkpoint recorded') else alert(r.data?.error)
  }

  const updateAssignmentProgress = async (assignmentId: string, status: string) => {
    const r = await api('POST', '/update-assignment-progress', { assignmentId, status, occurredAt: new Date().toISOString(), idempotencyKey: `prog-${assignmentId}-${Date.now()}` })
    if (r.ok) alert('Progress updated') else alert(r.data?.error)
  }

  const renderActions = (item: any) => {
    const btns: JSX.Element[] = []
    if (item.status === 'offered' || item.status === 'pending') {
      btns.push(<button key="acc" className="btn btn-success" style={{marginRight:8}} onClick={() => acceptAssignment(item.assignmentId)}>Accept</button>)
      btns.push(<button key="dec" className="btn btn-danger" style={{marginRight:8}} onClick={() => declineAssignment(item.assignmentId)}>Decline</button>)
    }
    if (item.kind === 'collection' && item.status === 'accepted') {
      btns.push(<button key="col" className="btn btn-primary" style={{marginRight:8}} onClick={() => collectSample(item.sampleId, item.assignmentId)}>Collect & Seal</button>)
    }
    if (item.status === 'in_progress') {
      btns.push(<button key="prog" className="btn btn-primary" style={{marginRight:8}} onClick={() => updateAssignmentProgress(item.assignmentId, 'in_transit')}>Update Progress</button>)
      btns.push(<button key="ck" className="btn btn-primary" style={{marginRight:8}} onClick={() => recordHandlingCheckpoint(item.sampleId, item.assignmentId)}>Checkpoint</button>)
    }
    if (auth.activeRole === 'laboratory_intake_operator' && item.status === 'in_progress') {
      btns.push(<button key="rec" className="btn btn-success" style={{marginRight:8}} onClick={() => confirmLabReceipt(item.sampleId, item.laboratoryId || '')}>Confirm Receipt</button>)
    }
    return btns
  }

  const allItems = work ? [...(work.pending||[]), ...(work.inProgress||[])] : []

  return (
    <div>
      <h3 style={{marginBottom:16}}>My Work — {auth.activeRole}</h3>
      <div className="grid-2">
        <div>
          {allItems.map((item: any, i: number) => (
            <div key={i} className="card" style={{padding:12,marginBottom:8,cursor:'pointer'}} onClick={() => setSelectedItem(item)}>
              <div className="info-row">
                <span className="badge badge-pending">{item.kind || 'assignment'}</span>
                <span className={`badge ${item.status==='completed'?'badge-done':item.status==='offered'?'badge-pending':'badge-active'}`}>{item.status}</span>
                {item.assignmentId && <span style={{fontSize:12,color:'#888'}}>{item.assignmentId?.slice(0,8)}...</span>}
              </div>
            </div>
          ))}
          {allItems.length === 0 && <p style={{color:'#888'}}>No work items</p>}
        </div>
        <div>
          {selectedItem && (
            <div className="card">
              <h3>Assignment {selectedItem.assignmentId?.slice(0,8)}...</h3>
              <div className="info-row" style={{marginBottom:12}}>
                <div className="info-item"><span>Status:</span> {selectedItem.status}</div>
                <div className="info-item"><span>Sample:</span> {selectedItem.sampleId?.slice(0,8)}...</div>
              </div>
              {selectedItem.fromLocationId && <div className="info-item"><span>From:</span> {selectedItem.fromLocationId?.slice(0,8)}...</div>}
              {selectedItem.toLocationId && <div className="info-item"><span>To:</span> {selectedItem.toLocationId?.slice(0,8)}...</div>}
              <div style={{marginTop:12}}>{renderActions(selectedItem)}</div>
              {selectedItem.history && selectedItem.history.length > 0 && (
                <div className="timeline" style={{marginTop:12}}>
                  {selectedItem.history.map((e: any, i: number) => (
                    <div key={i} className="tl-entry"><span>{e.action}</span><div className="tl-time">{new Date(e.occurredAt).toLocaleString()}</div></div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

