package main

import (
	"context"
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"lab-sample-system/internal/auth"
	"lab-sample-system/internal/events"
	"lab-sample-system/internal/handlers"
	"lab-sample-system/internal/middleware"
	"lab-sample-system/internal/models"
	"lab-sample-system/internal/service"
	"lab-sample-system/internal/store"

	"github.com/google/uuid"
	_ "github.com/lib/pq"
	"github.com/redis/go-redis/v9"
)

func main() {
	log.SetFlags(log.LstdFlags | log.Lshortfile)

	// Connect to PostgreSQL
	dbHost := envOrDefault("POSTGRES_HOST", "127.0.0.1")
	dbPort := envOrDefault("POSTGRES_PORT", "5432")
	dbUser := envOrDefault("POSTGRES_USER", "postgres")
	dbPass := envOrDefault("POSTGRES_PASSWORD", "postgres")
	dbName := envOrDefault("POSTGRES_DB", "postgres")

	dsn := fmt.Sprintf("host=%s port=%s user=%s password=%s dbname=%s sslmode=disable", dbHost, dbPort, dbUser, dbPass, dbName)
	db, err := sql.Open("postgres", dsn)
	if err != nil {
		log.Fatalf("Failed to connect to PostgreSQL: %v", err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := db.PingContext(ctx); err != nil {
		log.Fatalf("PostgreSQL ping failed: %v", err)
	}
	log.Println("Connected to PostgreSQL")

	// Connect to Redis
	redisHost := envOrDefault("REDIS_HOST", "127.0.0.1")
	redisPort := envOrDefault("REDIS_PORT", "6379")
	rdb := redis.NewClient(&redis.Options{
		Addr: fmt.Sprintf("%s:%s", redisHost, redisPort),
	})
	if _, err := rdb.Ping(context.Background()).Result(); err != nil {
		log.Fatalf("Redis ping failed: %v", err)
	}
	log.Println("Connected to Redis")

	// Initialize store
	st := store.New(db, rdb)
	svc := service.New(st)
	h := handlers.New(st, svc)
	hub := events.NewHub(st)

	// Compute initial serviceability snapshot
	go func() {
		svc.ComputeServiceabilitySnapshot(context.Background())
	}()

	// Set up initial admin
	adminUser := os.Getenv("ADMIN_USERNAME")
	adminPass := os.Getenv("ADMIN_PASSWORD")

	count, _ := st.UserCount(context.Background())
	if count == 0 && adminUser != "" && adminPass != "" {
		hash, _ := auth.HashPassword(adminPass)
		admin := &models.User{
			ID:           uuid.New().String(),
			Username:     adminUser,
			PasswordHash: hash,
			Roles:        []string{"administrator", "dispatcher", "requester"},
			Active:       true,
		}
		if err := st.CreateUser(context.Background(), admin); err != nil {
			log.Printf("Failed to create admin user: %v", err)
		} else {
			log.Printf("Created initial admin user: %s", adminUser)
		}
	}

	// Set up default sample types if none exist
	defaultSampleTypes := []models.SampleType{
		{
			Name:                      "Amber",
			QualifiedCollectorRequired: true,
			RequiredQualification:     "amber_collector",
			ContainerType:             "standard",
			BatchingAllowed:           true,
		},
		{
			Name:                      "Indigo",
			QualifiedCollectorRequired: true,
			RequiredQualification:     "indigo_collector",
			ContainerType:             "standard",
			IncompatibleSampleTypes:   []string{},
			BatchingAllowed:           true,
		},
		{
			Name:                      "Frost",
			QualifiedCollectorRequired: true,
			RequiredQualification:     "frost_collector",
			ContainerType:             "cooled",
			TemperatureMinC:           float64Ptr(2.0),
			TemperatureMaxC:           float64Ptr(8.0),
			RequiresCooledRoute:       true,
			BatchingAllowed:           true,
		},
		{
			Name:                      "Pulse",
			QualifiedCollectorRequired: true,
			RequiredQualification:     "pulse_collector",
			ContainerType:             "standard",
			BatchingAllowed:           false,
		},
	}

	existingTypes, _ := st.ListSampleTypes(context.Background())
	if len(existingTypes) == 0 {
		for i := range defaultSampleTypes {
			sType := &defaultSampleTypes[i]
			sType.ID = uuid.New().String()
			if err := st.CreateSampleType(context.Background(), sType); err != nil {
				log.Printf("Failed to create default sample type %s: %v", sType.Name, err)
			}
		}
		log.Println("Created default sample types")
	}

	// Set up routes
	authMW := middleware.AuthMiddleware(st)
	mux := http.NewServeMux()

	// Public routes
	mux.HandleFunc("GET /ready", h.SystemReadiness)
	mux.HandleFunc("POST /api/authenticate-user", h.AuthenticateUser)

	// Authenticated routes
	api := http.NewServeMux()

	// Auth
	api.HandleFunc("POST /api/select-active-role", h.SelectActiveRole)

	// User management (admin)
	api.HandleFunc("POST /api/create-user", h.CreateUser)
	api.HandleFunc("GET /api/read-user/{userId}", h.ReadUser)
	api.HandleFunc("POST /api/update-user-access", h.UpdateUserAccess)

	// Locations
	api.HandleFunc("POST /api/create-location", h.CreateLocation)
	api.HandleFunc("POST /api/update-location", h.UpdateLocation)
	api.HandleFunc("POST /api/set-location-status", h.SetLocationStatus)
	api.HandleFunc("POST /api/set-location-function-status", h.SetLocationFunctionStatus)
	api.HandleFunc("POST /api/configure-capacity", h.ConfigureCapacity)

	// Connections
	api.HandleFunc("POST /api/create-connection", h.CreateConnection)
	api.HandleFunc("POST /api/set-connection-status", h.SetConnectionStatus)

	// Sample Types
	api.HandleFunc("POST /api/create-sample-type", h.CreateSampleType)
	api.HandleFunc("POST /api/update-sample-type", h.UpdateSampleType)
	api.HandleFunc("POST /api/configure-laboratory-acceptance", h.ConfigureLaboratoryAcceptance)

	// Requests
	api.HandleFunc("POST /api/check-serviceability", h.CheckServiceability)
	api.HandleFunc("POST /api/create-collection-request", h.CreateCollectionRequest)
	api.HandleFunc("POST /api/ingest-presealed-sample", h.IngestPresealedSample)

	// Collection & Transport
	api.HandleFunc("POST /api/collect-and-seal-sample", h.CollectAndSealSample)
	api.HandleFunc("POST /api/accept-assignment", h.AcceptAssignment)
	api.HandleFunc("POST /api/decline-assignment", h.DeclineAssignment)
	api.HandleFunc("POST /api/update-assignment-progress", h.UpdateAssignmentProgress)
	api.HandleFunc("POST /api/initiate-handoff", h.InitiateHandoff)
	api.HandleFunc("POST /api/confirm-handoff", h.ConfirmHandoff)
	api.HandleFunc("POST /api/confirm-laboratory-receipt", h.ConfirmLaboratoryReceipt)
	api.HandleFunc("POST /api/record-handling-checkpoint", h.RecordHandlingCheckpoint)
	api.HandleFunc("POST /api/record-laboratory-exception", h.RecordLaboratoryException)
	api.HandleFunc("POST /api/record-worker-location", h.RecordWorkerLocation)
	api.HandleFunc("POST /api/set-worker-availability", h.SetWorkerAvailability)

	// Read operations
	api.HandleFunc("GET /api/read-sample-state/{sampleId}", h.ReadSampleState)
	api.HandleFunc("POST /api/read-sample-lifecycle", h.ReadSampleLifecycle)
	api.HandleFunc("POST /api/read-journey-plan", h.ReadJourneyPlan)
	api.HandleFunc("POST /api/read-operations-state", h.ReadOperationsState)
	api.HandleFunc("POST /api/read-serviceability-snapshot", h.ReadServiceabilitySnapshot)
	api.HandleFunc("POST /api/list-role-work", h.ListRoleWork)
	api.HandleFunc("POST /api/search-audit-trail", h.SearchAuditTrail)

	// Journey management
	api.HandleFunc("POST /api/cancel-journey", h.CancelJourney)
	api.HandleFunc("POST /api/reroute-journey", h.RerouteJourney)
	api.HandleFunc("POST /api/split-journey", h.SplitJourney)
	api.HandleFunc("POST /api/merge-journeys", h.MergeJourneys)
	api.HandleFunc("POST /api/edit-active-plan", h.EditActivePlan)
	api.HandleFunc("POST /api/report-disruption", h.ReportDisruption)

	// UI Bootstrap
	api.HandleFunc("GET /api/ui/bootstrap", h.ReadUIBootstrap)

	mux.Handle("/api/", authMW(api))
	mux.HandleFunc("/api/events", hub.HandleWebSocket)

	// Serve static frontend
	fs := http.FileServer(http.Dir("static"))
	mux.Handle("/", fs)

	port := envOrDefault("PORT", "8080")
	srv := &http.Server{
		Addr:    ":" + port,
		Handler: mux,
	}

	// CORS middleware wrapper
	handler := corsMiddleware(mux)

	go func() {
		log.Printf("Server starting on :%s", port)
		if err := http.ListenAndServe(":"+port, handler); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server failed: %v", err)
		}
	}()

	// Graceful shutdown
	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit
	log.Println("Shutting down...")
	ctx, cancel = context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	srv.Shutdown(ctx)
	log.Println("Server stopped")
}

func envOrDefault(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func float64Ptr(f float64) *float64 {
	return &f
}

func corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
		if r.Method == "OPTIONS" {
			w.WriteHeader(http.StatusOK)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func _unused() {
	_ = float64Ptr
}

