		for i := range defaultSampleTypes {
			sType := &defaultSampleTypes[i]
			sType.ID = uuid.New().String()
			if err := st.CreateSampleType(context.Background(), sType); err != nil {
				log.Printf("Failed to create default sample type %s: %v", sType.Name, err)
			}
		}
		log.Println("Created default sample types")
	}

	// Set up routes
	authMW := middleware.AuthMiddleware(st)
	mux := http.NewServeMux()

	// Public routes
	mux.HandleFunc("GET /ready", h.SystemReadiness)
	mux.HandleFunc("POST /api/authenticate-user", h.AuthenticateUser)

	// Helper
	auth := func(fn http.HandlerFunc) http.HandlerFunc {
		return authMW(http.HandlerFunc(fn)).ServeHTTP
	}

	// Auth
	mux.HandleFunc("POST /api/select-active-role", auth(h.SelectActiveRole))

	// User management (admin)
	mux.HandleFunc("POST /api/create-user", auth(h.CreateUser))
	mux.HandleFunc("GET /api/read-user/{userId}", auth(h.ReadUser))
	mux.HandleFunc("POST /api/update-user-access", auth(h.UpdateUserAccess))

	// Locations
	mux.HandleFunc("POST /api/create-location", auth(h.CreateLocation))
	mux.HandleFunc("POST /api/update-location", auth(h.UpdateLocation))
	mux.HandleFunc("POST /api/set-location-status", auth(h.SetLocationStatus))
	mux.HandleFunc("POST /api/set-location-function-status", auth(h.SetLocationFunctionStatus))
	mux.HandleFunc("POST /api/configure-capacity", auth(h.ConfigureCapacity))

	// Connections
	mux.HandleFunc("POST /api/create-connection", auth(h.CreateConnection))
	mux.HandleFunc("POST /api/set-connection-status", auth(h.SetConnectionStatus))

	// Sample Types
	mux.HandleFunc("POST /api/create-sample-type", auth(h.CreateSampleType))
	mux.HandleFunc("POST /api/update-sample-type", auth(h.UpdateSampleType))
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", auth(h.ConfigureLaboratoryAcceptance))

	// Requests
	mux.HandleFunc("POST /api/check-serviceability", auth(h.CheckServiceability))
	mux.HandleFunc("POST /api/create-collection-request", auth(h.CreateCollectionRequest))
	mux.HandleFunc("POST /api/ingest-presealed-sample", auth(h.IngestPresealedSample))

	// Collection & Transport
	mux.HandleFunc("POST /api/collect-and-seal-sample", auth(h.CollectAndSealSample))
	mux.HandleFunc("POST /api/accept-assignment", auth(h.AcceptAssignment))
	mux.HandleFunc("POST /api/decline-assignment", auth(h.DeclineAssignment))
	mux.HandleFunc("POST /api/update-assignment-progress", auth(h.UpdateAssignmentProgress))
	mux.HandleFunc("POST /api/initiate-handoff", auth(h.InitiateHandoff))
	mux.HandleFunc("POST /api/confirm-handoff", auth(h.ConfirmHandoff))
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", auth(h.ConfirmLaboratoryReceipt))
	mux.HandleFunc("POST /api/record-handling-checkpoint", auth(h.RecordHandlingCheckpoint))
	mux.HandleFunc("POST /api/record-laboratory-exception", auth(h.RecordLaboratoryException))
	mux.HandleFunc("POST /api/record-worker-location", auth(h.RecordWorkerLocation))
	mux.HandleFunc("POST /api/set-worker-availability", auth(h.SetWorkerAvailability))

	// Read operations
	mux.HandleFunc("GET /api/read-sample-state/{sampleId}", auth(h.ReadSampleState))
	mux.HandleFunc("POST /api/read-sample-lifecycle", auth(h.ReadSampleLifecycle))
	mux.HandleFunc("POST /api/read-journey-plan", auth(h.ReadJourneyPlan))
	mux.HandleFunc("POST /api/read-operations-state", auth(h.ReadOperationsState))
	mux.HandleFunc("POST /api/read-serviceability-snapshot", auth(h.ReadServiceabilitySnapshot))
	mux.HandleFunc("POST /api/list-role-work", auth(h.ListRoleWork))
	mux.HandleFunc("POST /api/search-audit-trail", auth(h.SearchAuditTrail))

	// Journey management
	mux.HandleFunc("POST /api/cancel-journey", auth(h.CancelJourney))
	mux.HandleFunc("POST /api/reroute-journey", auth(h.RerouteJourney))
	mux.HandleFunc("POST /api/split-journey", auth(h.SplitJourney))
	mux.HandleFunc("POST /api/merge-journeys", auth(h.MergeJourneys))
	mux.HandleFunc("POST /api/edit-active-plan", auth(h.EditActivePlan))
	mux.HandleFunc("POST /api/report-disruption", auth(h.ReportDisruption))

	// UI Bootstrap
	mux.HandleFunc("GET /api/ui/bootstrap", auth(h.ReadUIBootstrap))

	// WebSocket
	mux.HandleFunc("/api/events", hub.HandleWebSocket)

	// Serve static frontend
	fs := http.FileServer(http.Dir("static"))
	mux.Handle("/", fs)

	port := envOrDefault("PORT", "8080")
	srv := &http.Server{
		Addr:    ":" + port,
		Handler: mux,
	}

	// CORS middleware wrapper
	handler := corsMiddleware(mux)

	go func() {
		log.Printf("Server starting on :%s", port)
		if err := http.ListenAndServe(":"+port, handler); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server failed: %v", err)
		}
	}()

	// Graceful shutdown
	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit
	log.Println("Shutting down...")
	ctx, cancel = context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	srv.Shutdown(ctx)
	log.Println("Server stopped")
}

func envOrDefault(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func float64Ptr(f float64) *float64 {
	return &f
}

func corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Authorization")
		if r.Method == "OPTIONS" {
			w.WriteHeader(http.StatusOK)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func _unused() {
	_ = float64Ptr
}

