function ConnectionManagement() {
  const [fromId, setFromId] = useState('')
  const [toId, setToId] = useState('')
  const [travelMinutes, setTravel] = useState(30)
  const [costUnits, setCost] = useState(10)
  const [cooled, setCooled] = useState(false)
  const [active, setActive] = useState(true)
  const [msg, setMsg] = useState('')

  const create = async () => {
    setMsg('')
    const r = await api('POST', '/create-connection', { fromLocationId: fromId, toLocationId: toId, travelMinutes, costUnits, cooled, active })
    setMsg(r.ok ? `Created ${r.data?.data?.connectionId}` : r.data?.error || 'Failed')
  }

  return (
    <div>
      <h3 style={{marginBottom:16}}>Connection Management</h3>
      <div className="card">
        <h3>Create Connection</h3>
        <div className="form-row">
          <div className="form-group"><label>From Location ID</label><input value={fromId} onChange={e => setFromId(e.target.value)} /></div>
          <div className="form-group"><label>To Location ID</label><input value={toId} onChange={e => setToId(e.target.value)} /></div>
        </div>
        <div className="form-row">
          <div className="form-group"><label>Travel (min)</label><input type="number" value={travelMinutes} onChange={e => setTravel(+e.target.value)} /></div>
          <div className="form-group"><label>Cost Units</label><input type="number" value={costUnits} onChange={e => setCost(+e.target.value)} /></div>
        </div>
        <div className="form-row">
          <div className="form-group"><label>Cooled</label><select value={String(cooled)} onChange={e => setCooled(e.target.value==='true')}><option value="true">Yes</option><option value="false">No</option></select></div>
          <div className="form-group"><label>Active</label><select value={String(active)} onChange={e => setActive(e.target.value==='true')}><option value="true">Yes</option><option value="false">No</option></select></div>
        </div>
        <button className="btn btn-primary" onClick={create}>Create Connection</button>
      </div>
      {msg && <div className={msg.includes('Created')?'success-banner':'error-banner'}>{msg}</div>}
    </div>
  )
}

