    25	func AuthMiddleware(s *store.Store) func(http.Handler) http.Handler {
    26		return func(next http.Handler) http.Handler {
    27			return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    28				auth := r.Header.Get("Authorization")
    29				if auth == "" || !strings.HasPrefix(auth, "Bearer ") {
    30					writeError(w, http.StatusUnauthorized, "unauthorized", "missing or invalid token")
    31					return
    32				}
    33				token := strings.TrimPrefix(auth, "Bearer ")
    34				userID, activeRole, err := s.GetSession(r.Context(), token)
    35				if err != nil {
    36					writeError(w, http.StatusUnauthorized, "unauthorized", "invalid session")
    37					return
    38				}
    39				ctx := context.WithValue(r.Context(), SessionKey, &Session{UserID: userID, ActiveRole: activeRole})
    40				ctx = context.WithValue(ctx, UserIDKey, userID)
    41				ctx = context.WithValue(ctx, RoleKey, activeRole)
    42				next.ServeHTTP(w, r.WithContext(ctx))
    43			})
    44		}
    45	}
    46	
    47	func RequireRoles(roles ...string) func(http.Handler) http.Handler {
    48		return func(next http.Handler) http.Handler {
    49			return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
    50				role := GetRole(r.Context())
    51				for _, allowed := range roles {
    52					if role == allowed {
    53						next.ServeHTTP(w, r)
    54						return
    55					}
    56				}
    57				writeError(w, http.StatusForbidden, "forbidden", "role not permitted")
    58			})
    59		}
    60	}
