   173	func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
   174		const R = 6371.0
   175		dLat := (lat2 - lat1) * math.Pi / 180.0
   176		dLon := (lon2 - lon1) * math.Pi / 180.0
   177		a := math.Sin(dLat/2)*math.Sin(dLat/2) +
   178			math.Cos(lat1*math.Pi/180.0)*math.Cos(lat2*math.Pi/180.0)*
   179				math.Sin(dLon/2)*math.Sin(dLon/2)
   180		c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
   181		return R * c
   182	}
