func (s *Store) ListSampleTypes(ctx context.Context) ([]models.SampleType, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed FROM sample_types`)
