// --- Laboratory Acceptance ---

func (s *Store) SetLaboratoryAcceptance(ctx context.Context, labID, sampleTypeID string, accepts bool) (string, error) {
	id := uuid.New().String()
	_, err := s.db.ExecContext(ctx, `
		INSERT INTO laboratory_acceptance (id, laboratory_id, sample_type_id, accepts)
		VALUES ($1, $2, $3, $4) ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=$4`,
