func (s *Store) GetLabAcceptedSampleTypes(ctx context.Context, labID string) ([]string, error) {
	rows, err := s.db.QueryContext(ctx, `SELECT sample_type_id FROM laboratory_acceptance WHERE laboratory_id=$1 AND accepts=true`, labID)
