// --- Samples ---

func (s *Store) CreateSample(ctx context.Context, sm *models.Sample) error {
	_, err := s.db.ExecContext(ctx, `
		INSERT INTO samples (id, request_id, requester_id, status, sealed, origin_lat, origin_lon, origin_type, origin_node_id,
			requested_at, delivery_deadline, sample_type_id, container_type, temperature_min_c, temperature_max_c,
			incompatible_sample_types, serviceability, serviceability_reason, state, active_journey_id, target_laboratory_id,
			current_holder_id, latest_location_lat, latest_location_lon, location_recorded_at, location_stale,
