package service

import (
	"context"
	"fmt"
	"math"
	"time"

	"lab-sample-system/internal/models"
	"lab-sample-system/internal/store"

	"github.com/google/uuid"
)

type Service struct {
	store *store.Store
}

func New(s *store.Store) *Service {
	return &Service{store: s}
}

func (s *Service) CheckServiceability(ctx context.Context, origin models.Coordinate, originType string, originNodeID *string, sampleTypeID string, earliestCollectionAt, latestCollectionAt, deliveryDeadline time.Time) (*models.ServiceabilityResult, error) {
	locs, err := s.store.ListLocations(ctx)
	if err != nil {
		return nil, err
	}

	_, err = s.store.GetSampleType(ctx, sampleTypeID)
	if err != nil {
		return &models.ServiceabilityResult{
			Serviceable:          false,
			Reason:               "unknown sample type",
			ServiceabilityVersion: 1,
		}, nil
	}

	// Find nearest active collection point
	type scoredLoc struct {
		loc      models.Location
		distance float64
	}
	var collectionPoints []scoredLoc

	for _, l := range locs {
		if !l.Active {
			continue
		}
		cp := l.Functions.CollectionPoint
		if cp != nil && !*cp {
			continue
		}
		if cp == nil {
			// Default: if no functions defined, not a collection point
			continue
		}
		d := haversineKm(origin.Latitude, origin.Longitude, l.Coordinate.Latitude, l.Coordinate.Longitude)
		collectionPoints = append(collectionPoints, scoredLoc{l, d})
	}

	if len(collectionPoints) == 0 {
		return &models.ServiceabilityResult{
			Serviceable:          false,
			Reason:               "no active collection points in network",
			ServiceabilityVersion: 1,
		}, nil
	}

	// Check if within 5km of nearest collection point
	minDist := collectionPoints[0].distance
	for _, cp := range collectionPoints {
		if cp.distance < minDist {
			minDist = cp.distance
		}
	}
	if minDist > 5.0 {
		return &models.ServiceabilityResult{
			Serviceable:          false,
			Reason:               fmt.Sprintf("origin %.1f km from nearest collection point (max 5 km)", minDist),
			ServiceabilityVersion: 1,
		}, nil
	}

	// Find active laboratories that accept this sample type
	var eligibleLabs []models.Location
	conns, _ := s.store.ListConnections(ctx)

	for _, l := range locs {
		if !l.Active {
			continue
		}
		lab := l.Functions.Laboratory
		if lab == nil || !*lab {
			continue
		}
		accepted, _ := s.store.GetLabAcceptedSampleTypes(ctx, l.ID)
		for _, acceptedID := range accepted {
			if acceptedID == sampleTypeID {
				eligibleLabs = append(eligibleLabs, l)
				break
			}
		}
	}

	if len(eligibleLabs) == 0 {
		return &models.ServiceabilityResult{
			Serviceable:          false,
			Reason:               "no laboratory accepts this sample type",
			ServiceabilityVersion: 1,
		}, nil
	}

	// Check if any connection path exists from a collection point to an eligible lab
	// Simple BFS through the connection graph
	connMap := make(map[string][]models.Connection)
	for _, c := range conns {
		if !c.Active {
			continue
		}
		connMap[c.FromLocationID] = append(connMap[c.FromLocationID], c)
	}

	// Check path from each collection point to each eligible lab
	for _, cp := range collectionPoints {
		if cp.distance > cp.loc.CoverageKm {
			continue
		}
		for _, lab := range eligibleLabs {
			visited := make(map[string]bool)
			queue := []string{cp.loc.ID}
			for len(queue) > 0 {
				current := queue[0]
				queue = queue[1:]
				if current == lab.ID {
					// Found path! Estimate arrival time
					totalMinutes := 0
					for _, c := range conns {
						if c.FromLocationID == cp.loc.ID || c.ToLocationID == lab.ID {
							totalMinutes += c.TravelMinutes
						}
					}
					if totalMinutes == 0 {
						totalMinutes = 30 // default
					}
					arrival := latestCollectionAt.Add(time.Duration(totalMinutes) * time.Minute)
					labID := lab.ID
					return &models.ServiceabilityResult{
						Serviceable:          true,
						Reason:               "serviceable",
						TargetLaboratoryID:   &labID,
						EstimatedArrivalAt:   &arrival,
						ServiceabilityVersion: 1,
					}, nil
				}
				if visited[current] {
					continue
				}
				visited[current] = true
				for _, c := range connMap[current] {
					queue = append(queue, c.ToLocationID)
				}
			}
		}
	}

	return &models.ServiceabilityResult{
		Serviceable:          false,
		Reason:               "no route available from collection point to accepting laboratory",
		ServiceabilityVersion: 1,
	}, nil
}

func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180.0
	dLon := (lon2 - lon1) * math.Pi / 180.0
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180.0)*math.Cos(lat2*math.Pi/180.0)*
			math.Sin(dLon/2)*math.Sin(dLon/2)
	c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
	return R * c
}

func (s *Service) ComputeServiceabilitySnapshot(ctx context.Context) error {
	locs, err := s.store.ListLocations(ctx)
	if err != nil {
		return err
	}

	version := fmt.Sprintf("%d", time.Now().Unix())
	regions := []models.ServiceabilityRegion{}
	activeCount := 0

	for _, l := range locs {
		if l.Active {
			cp := l.Functions.CollectionPoint
			if cp != nil && *cp {
				activeCount++
				regions = append(regions, models.ServiceabilityRegion{
					LocationID: l.ID,
					Name:       l.Name,
					Latitude:   l.Coordinate.Latitude,
					Longitude:   l.Coordinate.Longitude,
					CoverageKm: l.CoverageKm,
				})
			}
		}
	}

	return s.store.SaveServiceabilitySnapshot(ctx, version, time.Now().UTC(), uuid.New().String(), activeCount, regions)
}

