	acceptID, err := h.Store.SetLaboratoryAcceptance(r.Context(), req.LaboratoryID, req.SampleTypeID, req.Accepts)
	if err != nil {
		errResp(w, 500, "internal_error", "failed to configure acceptance")
		return
	}

	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"acceptanceId": acceptID,
			"accepts":      req.Accepts,
		},
	})
}

