// ReadSampleState
func (h *Handler) ReadSampleState(w http.ResponseWriter, r *http.Request) {
	sampleID := r.PathValue("sampleId")
	sm, err := h.Store.GetSample(r.Context(), sampleID)
	if err != nil {
		errResp(w, 404, "not_found", "sample not found")
		return
	}

	resp := map[string]interface{}{
		"data": map[string]interface{}{
			"sampleId":                 sm.ID,
			"requestId":                sm.RequestID,
			"requesterId":              sm.RequesterID,
			"origin":                   sm.Origin,
			"originType":               sm.OriginType,
			"requestedAt":              sm.RequestedAt,
			"deliveryDeadline":         sm.DeliveryDeadline,
			"sampleTypeId":             sm.SampleTypeID,
			"containerType":            sm.ContainerType,
			"temperatureMinC":          sm.TemperatureMinC,
			"temperatureMaxC":          sm.TemperatureMaxC,
			"incompatibleSampleTypes":  sm.IncompatibleSampleTypes,
			"serviceability":           sm.Serviceability,
			"activeAssignmentIds":      sm.ActiveAssignmentIDs,
			"state":                    sm.State,
			"timeline":                 sm.Timeline,
			"activeJourneyId":          sm.ActiveJourneyID,
			"targetLaboratoryId":       sm.TargetLaboratoryID,
			"latestLocation":           sm.LatestLocation,
			"locationRecordedAt":       sm.LocationRecordedAt,
			"locationStale":            sm.LocationStale,
		},
