// ReadOperationsState
func (h *Handler) ReadOperationsState(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Filters map[string]interface{} `json:"filters"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	// Build operations state
	samples, _ := h.Store.ListSamples(r.Context())
	locs, _ := h.Store.ListLocations(r.Context())
	conns, _ := h.Store.ListConnections(r.Context())

	opsState := models.OperationsState{
		Samples:                   make([]map[string]interface{}, 0),
		Workers:                   make([]map[string]interface{}, 0),
		Locations:                 make([]map[string]interface{}, 0),
		Connections:               make([]map[string]interface{}, 0),
		Routes:                    make([]map[string]interface{}, 0),
		Handoffs:                  make([]map[string]interface{}, 0),
		Delays:                    make([]map[string]interface{}, 0),
		Exceptions:                make([]map[string]interface{}, 0),
		AssignmentCountSpread:     0,
		IneligibleAssignmentCount: 0,
	}

	for _, sm := range samples {
		m := map[string]interface{}{
			"sampleId":       sm.ID,
			"sample_id":      sm.ID,
			"status":         sm.Status,
			"requestId":      sm.RequestID,
			"deliveryDeadline": sm.DeliveryDeadline,
			"locationStale":  sm.LocationStale,
		}
		if sm.Origin.Latitude != 0 {
			m["origin"] = sm.Origin
		}
		if sm.CurrentHolderID != nil {
			m["currentHolderId"] = *sm.CurrentHolderID
		}
		if sm.ActiveJourneyID != nil {
			m["activeJourneyId"] = *sm.ActiveJourneyID
		}
		if sm.LatestLocation != nil {
			m["latestLocation"] = sm.LatestLocation
		}
		if sm.LocationRecordedAt != nil {
			m["locationRecordedAt"] = *sm.LocationRecordedAt
		}
		opsState.Samples = append(opsState.Samples, m)
	}

	for _, l := range locs {
		cap, _ := h.Store.GetLocationCapacity(r.Context(), l.ID)
		accepted, _ := h.Store.GetLabAcceptedSampleTypes(r.Context(), l.ID)
		m := map[string]interface{}{
			"id":             l.ID,
			"locationId":     l.ID,
			"name":           l.Name,
			"coordinate":     l.Coordinate,
			"active":         l.Active,
			"coverageKm":     l.CoverageKm,
			"handlingMinutes": l.HandlingMinutes,
			"functions":      l.Functions,
			"capacity":       cap,
			"acceptedSampleTypeIds": accepted,
		}
		opsState.Locations = append(opsState.Locations, m)
	}

	for _, c := range conns {
		cap, _ := h.Store.GetConnectionCapacity(r.Context(), c.ID)
		m := map[string]interface{}{
			"id":             c.ID,
			"connectionId":   c.ID,
			"fromLocationId": c.FromLocationID,
			"toLocationId":   c.ToLocationID,
			"travelMinutes":  c.TravelMinutes,
			"costUnits":      c.CostUnits,
			"cooled":         c.Cooled,
			"active":         c.Active,
			"capacity":       cap,
		}
		opsState.Connections = append(opsState.Connections, m)
	}

	respond(w, 200, map[string]interface{}{
		"data": opsState,
	})
}

