		return
	}

	resp := map[string]interface{}{
		"data": map[string]interface{}{
			"sampleId":                  sm.ID,
			"status":                    sm.Status,
			"sealed":                    sm.Sealed,
			"completedLegIds":           sm.CompletedLegIDs,
			"activeReplacementPlanIds":  sm.ActiveReplacementPlanIDs,
			"timeline":                  sm.Timeline,
			"locationStale":             sm.LocationStale,
		},
	}

