===COLLECT===
func (h *Handler) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
        var req struct {
                AssignmentID   string `json:"assignmentId"`
                IdempotencyKey string `json:"idempotencyKey"`
        }
        if err := getReqBody(r, &req); err != nil {
                errResp(w, 400, "invalid_json", "invalid request body")
                return
        }

        if req.IdempotencyKey == "" {
                errResp(w, 400, "idempotency_required", "idempotencyKey required")
                return
        }

        if cached, found, _ := h.Store.CheckIdempotency(r.Context(), req.IdempotencyKey); found {
                var resp map[string]interface{}
                json.Unmarshal(cached, &resp)
                respond(w, 201, resp)
                return
        }

        userID := middleware.GetUserID(r.Context())
        role := middleware.GetRole(r.Context())

        a, err := h.Store.GetAssignment(r.Context(), req.AssignmentID)
        if err != nil {
                errResp(w, 404, "not_found", "assignment not found")
                return
        }

        if a.Status != "offered" {
                errResp(w, 409, "assignment_inactive", "assignment is not in offered state")
                return
        }

        if a.WorkerID != nil && *a.WorkerID != userID {
                errResp(w, 403, "ineligible_worker", "assignment not offered to this worker")
                return
        }

        if a.OfferExpiresAt != nil && time.Now().After(*a.OfferExpiresAt) {
                errResp(w, 409, "offer_not_available", "offer has expired")
                return
        }

        a.Status = "accepted"
        a.WorkerID = &userID
        a.OfferExpiresAt = nil

        if err := h.Store.UpdateAssignment(r.Context(), a); err != nil {
                errResp(w, 500, "internal_error", "update failed")
                return
        }

        // Update sample state if collection assignment
        sm, _ := h.Store.GetSample(r.Context(), a.SampleID)
        if sm != nil {
                sm.State = "assigned"
                sm.CurrentHolderID = &userID
                h.Store.UpdateSample(r.Context(), sm)
        }

        h.Store.AddAssignmentTimeline(r.Context(), models.TimelineEntry{
                EventID:    uuid.New().String(),
                Action:     "assignment_accepted",
                ActorID:    userID,
                Role:       role,
                EntityType: "assignment",
                EntityID:   a.ID,
                Success:    true,
                OccurredAt: time.Now().UTC(),
                Details:    "Assignment accepted",
        })

        h.Store.IncrementWorkerAssignment(r.Context(), userID)
        h.writeAudit(r.Context(), userID, role, "assignment.accepted", "assignment", a.ID, true, "")

        resp := map[string]interface{}{
                "data": map[string]interface{}{
                        "assignmentId": a.ID,
                        "workerId":     userID,
                        "status":       "accepted",
                },
        }
        b, _ := json.Marshal(resp)
        h.Store.SetIdempotency(r.Context(), req.IdempotencyKey, b)
        respond(w, 201, resp)
}

