                SampleTypeID          string            `json:"sampleTypeId"`
                ContainerType         string            `json:"containerType"`
                TemperatureMinC       *float64          `json:"temperatureMinC"`
                TemperatureMaxC       *float64          `json:"temperatureMaxC"`
                IncompatibleSampleTypes []string        `json:"incompatibleSampleTypes"`
                IdempotencyKey        string            `json:"idempotencyKey"`
        }
        if err := getReqBody(r, &req); err != nil {
                errResp(w, 400, "invalid_json", "invalid request body")
                return
        }

        if req.IdempotencyKey == "" {
                errResp(w, 400, "idempotency_required", "idempotencyKey required")
                return
        }

        if cached, found, _ := h.Store.CheckIdempotency(r.Context(), req.IdempotencyKey); found {
                var resp map[string]interface{}
                json.Unmarshal(cached, &resp)
                respond(w, 201, resp)
                return
        }

        // Check serviceability
        svcResult, err := h.Service.CheckServiceability(r.Context(), req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, req.EarliestCollectionAt, req.LatestCollectionAt, req.DeliveryDeadline)
        if err != nil || !svcResult.Serviceable {
                reason := "not serviceable"
                if err != nil {
                        reason = err.Error()
                } else {
                        reason = svcResult.Reason
                }
                errResp(w, 409, "state_snapshot_changed", reason)
                return
        }

        requestID := uuid.New().String()
        sampleID := uuid.New().String()

        sm := &models.Sample{
                ID:                      sampleID,
                RequestID:               requestID,
                RequesterID:             req.RequesterID,
                Status:                  "requested",
                Sealed:                  false,
                Origin:                  req.Origin,
                OriginType:              req.OriginType,
                OriginNodeID:            req.OriginNodeID,
                RequestedAt:             req.RequestedAt,
                DeliveryDeadline:        req.DeliveryDeadline,
                SampleTypeID:            req.SampleTypeID,
                ContainerType:           req.ContainerType,
                TemperatureMinC:         req.TemperatureMinC,
                TemperatureMaxC:         req.TemperatureMaxC,
                IncompatibleSampleTypes: req.IncompatibleSampleTypes,
                Serviceability:          boolToString(svcResult.Serviceable),
                ServiceabilityReason:    svcResult.Reason,
                State:                   "requested",
                TargetLaboratoryID:      svcResult.TargetLaboratoryID,
                LocationStale:           true,
                EarliestCollectionAt:    req.EarliestCollectionAt,
                LatestCollectionAt:      req.LatestCollectionAt,
        }

        if err := h.Store.CreateSample(r.Context(), sm); err != nil {
                errResp(w, 500, "internal_error", "failed to create sample")
                return
        }

        // Create journey if serviceable
        var journeyID *string
        if svcResult.Serviceable && svcResult.TargetLaboratoryID != nil {
                j := &models.Journey{
                        ID:                   uuid.New().String(),
                        PlanVersion:          1,
                        RouteMode:            "direct",
                        Status:               "planned",
                        SampleIDs:            []string{sampleID},
                        EstimatedDeliveryAt:  svcResult.EstimatedArrivalAt,
                        TotalCostUnits:       0,
                        CapacityUsed:         1,
                        CapacityAvailable:    1,
                        Valid:                true,
                        CollectionAssignmentIDs: []string{},
                        NodeAssignmentIDs:       []string{},
                        LaboratoryAssignmentIDs: []string{},
                }

                // Add stops
                collectionStop := models.JourneyStop{
                        StopID:     uuid.New().String(),
                        LocationID: *svcResult.TargetLaboratoryID, // using nearest collection point
                        StopType:   "collection",
                        Sequence:   1,
                        EstimatedAt: req.EarliestCollectionAt,
                        Coordinate: &req.Origin,
                }
                labStop := models.JourneyStop{
                        StopID:      uuid.New().String(),
                        LocationID:  *svcResult.TargetLaboratoryID,
                        StopType:    "laboratory",
                        Sequence:    2,
                        EstimatedAt: req.DeliveryDeadline,
                }
                j.OrderedStops = []models.JourneyStop{collectionStop, labStop}

                if err := h.Store.CreateJourney(r.Context(), j); err != nil {
                        log.Printf("journey creation error: %v", err)
                } else {
                        journeyID = &j.ID
                        sm.ActiveJourneyID = journeyID
                        sm.Status = "planned"
                        sm.State = "planned"
                        h.Store.UpdateSample(r.Context(), sm)
                }
        }

        // Write timeline
        now := time.Now().UTC()
        h.Store.AddSampleTimeline(r.Context(), models.TimelineEntry{
                EventID:    uuid.New().String(),
                Action:     "request_created",
                ActorID:    req.RequesterID,
                Role:       "requester",
                EntityType: "sample",
                EntityID:   sampleID,
                Success:    true,
                OccurredAt: now,
                Details:    "Collection request created",
        })

        h.writeAudit(r.Context(), req.RequesterID, middleware.GetRole(r.Context()), "request.created", "sample", sampleID, true, "")

        svcStr := "unserviceable"
        if svcResult.Serviceable {
                svcStr = "serviceable"
        }
        resp := map[string]interface{}{
                "data": map[string]interface{}{
                        "requestId":            requestID,
                        "sampleId":             sampleID,
                        "serviceability":       svcStr,
                        "serviceabilityReason": svcResult.Reason,
                        "activeAssignmentIds":  []string{},
                        "earliestCollectionAt": req.EarliestCollectionAt,
                        "latestCollectionAt":   req.LatestCollectionAt,
                        "alreadySealed":        false,
                        "originType":           req.OriginType,
                },
        }

        if journeyID != nil {
                resp["data"].(map[string]interface{})["journeyId"] = *journeyID
        }
        if svcResult.TargetLaboratoryID != nil {
                resp["data"].(map[string]interface{})["targetLaboratoryId"] = *svcResult.TargetLaboratoryID
        }

        b, _ := json.Marshal(resp)
