// SearchAuditTrail
func (h *Handler) SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Query      string     `json:"query"`
		ActorID    string     `json:"actorId"`
		EntityType string     `json:"entityType"`
		EntityID   string     `json:"entityId"`
		Action     string     `json:"action"`
		Role       string     `json:"role"`
		Success    *bool      `json:"success"`
		FromTime   *time.Time `json:"fromTime"`
		ToTime     *time.Time `json:"toTime"`
		Limit      int        `json:"limit"`
		Offset     int        `json:"offset"`
		Order      string     `json:"order"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	if req.Order == "" {
		req.Order = "newest_first"
	}

	params := store.AuditSearchParams{
		ActorID:    req.ActorID,
		EntityType: req.EntityType,
		EntityID:   req.EntityID,
		Action:     req.Action,
		Role:       req.Role,
		Success:    req.Success,
		FromTime:   req.FromTime,
		ToTime:     req.ToTime,
		Limit:      req.Limit,
		Offset:     req.Offset,
		Order:      req.Order,
	}

	result, err := h.Store.SearchAudit(r.Context(), params)
	if err != nil {
