// ReadUIBootstrap
func (h *Handler) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	user, err := h.Store.GetUserByID(r.Context(), userID)
	if err != nil {
		errResp(w, 401, "unauthorized", "user not found")
		return
	}

	samples, _ := h.Store.ListSamples(r.Context())
	requesterSamples := []map[string]interface{}{}
	for _, sm := range samples {
		if sm.RequesterID == userID {
			requesterSamples = append(requesterSamples, map[string]interface{}{
				"sampleId":  sm.ID,
				"requestId": sm.RequestID,
				"status":    sm.Status,
			})
		}
	}

	ops := h.buildOperationsState(r.Context())

	respond(w, 200, map[string]interface{}{
		"data": map[string]interface{}{
			"user": map[string]interface{}{
				"userId": user.ID,
				"username": user.Username,
				"roles": user.Roles,
			},
			"serverTime":       time.Now().UTC(),
			"requesterSamples": requesterSamples,
			"operations":       ops,
		},
	})
}

