	}

	result, err := h.Service.CheckServiceability(r.Context(), req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, req.EarliestCollectionAt, req.LatestCollectionAt, req.DeliveryDeadline)
	if err != nil {
