	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	sm, err := h.Store.GetSample(r.Context(), req.SampleID)
	if err != nil {
		errResp(w, 404, "not_found", "sample not found")
		return
	}

	resp := map[string]interface{}{
		"data": map[string]interface{}{
			"sampleId":                  sm.ID,
			"status":                    sm.Status,
			"sealed":                    sm.Sealed,
			"completedLegIds":           sm.CompletedLegIDs,
			"activeReplacementPlanIds":  sm.ActiveReplacementPlanIDs,
			"timeline":                  sm.Timeline,
			"locationStale":             sm.LocationStale,
		},
	}

	if sm.ActiveJourneyID != nil {
