// RecordHandlingCheckpoint
func (h *Handler) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	var req struct {
		SampleID             string    `json:"sampleId"`
		AssignmentID         string    `json:"assignmentId"`
		LocationID           string    `json:"locationId"`
		ContainerType        string    `json:"containerType"`
		ObservedTemperatureC float64   `json:"observedTemperatureC"`
		RecordedAt           time.Time `json:"recordedAt"`
		IdempotencyKey       string    `json:"idempotencyKey"`
	}
	if err := getReqBody(r, &req); err != nil {
		errResp(w, 400, "invalid_json", "invalid request body")
		return
	}

	cpID, err := h.Store.RecordHandlingCheckpoint(r.Context(), req.SampleID, req.AssignmentID, req.LocationID, req.ContainerType, req.ObservedTemperatureC, req.RecordedAt)
	if err != nil {
		errResp(w, 500, "internal_error", "checkpoint recording failed")
		return
	}

	// Check compliance
	sm, _ := h.Store.GetSample(r.Context(), req.SampleID)
	compliant := true
	if sm != nil {
		if sm.TemperatureMinC != nil && req.ObservedTemperatureC < *sm.TemperatureMinC {
			compliant = false
		}
		if sm.TemperatureMaxC != nil && req.ObservedTemperatureC > *sm.TemperatureMaxC {
			compliant = false
		}
		if !compliant {
			exc := "handling_noncompliant"
			sm.Exception = &exc
			h.Store.UpdateSample(r.Context(), sm)
		}
	}

	sampleStatus := "in_transit"
	if sm != nil {
		sampleStatus = sm.Status
	}

	respond(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"checkpointId":  cpID,
			"sampleId":      req.SampleID,
			"compliant":     compliant,
			"sampleStatus":  sampleStatus,
		},
	})
}

