                DeliveryDeadline     time.Time         `json:"deliveryDeadline"`
                EarliestCollectionAt time.Time         `json:"earliestCollectionAt"`
                LatestCollectionAt   time.Time         `json:"latestCollectionAt"`
        }
        if err := getReqBody(r, &req); err != nil {
                errResp(w, 400, "invalid_json", "invalid request body")
                return
        }

        result, err := h.Service.CheckServiceability(r.Context(), req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, req.EarliestCollectionAt, req.LatestCollectionAt, req.DeliveryDeadline)
        if err != nil {
                errResp(w, 500, "internal_error", "serviceability check failed")
                return
        }

        respond(w, 200, map[string]interface{}{"data": result})
}

