func (h *Handler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
        var req struct {
                Username string `json:"username"`
                Password string `json:"password"`
        }
        if err := getReqBody(r, &req); err != nil {
                errResp(w, 400, "invalid_json", "invalid request body")
                return
        }
        if req.Username == "" || req.Password == "" {
                errResp(w, 400, "invalid_json", "username and password required")
                return
        }

        user, err := h.Store.GetUserByUsername(r.Context(), req.Username)
        if err != nil {
                errResp(w, 401, "unauthorized", "invalid credentials")
                return
        }
        if !user.Active {
                errResp(w, 401, "unauthorized", "account deactivated")
                return
        }
        if !auth.CheckPassword(req.Password, user.PasswordHash) {
                errResp(w, 401, "unauthorized", "invalid credentials")
                return
        }

        token, err := auth.GenerateToken()
        if err != nil {
                errResp(w, 500, "internal_error", "failed to create session")
                return
        }

        activeRole := ""
        if len(user.Roles) > 0 {
                activeRole = user.Roles[0]
        }

        if err := h.Store.CreateSession(r.Context(), token, user.ID, activeRole, 24*time.Hour); err != nil {
                errResp(w, 500, "internal_error", "failed to create session")
                return
        }

        respond(w, 200, map[string]interface{}{
                "data": map[string]interface{}{
                        "sessionToken": token,
                        "userId":       user.ID,
                        "roles":        user.Roles,
                        "activeRole":   activeRole,
                },
        })
}

func (h *Handler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
        var req struct {
                Role string `json:"role"`
        }
        if err := getReqBody(r, &req); err != nil {
                errResp(w, 400, "invalid_json", "invalid request body")
                return
        }

        userID := middleware.GetUserID(r.Context())
        user, err := h.Store.GetUserByID(r.Context(), userID)
        if err != nil {
                errResp(w, 404, "not_found", "user not found")
                return
        }

        valid := false
        for _, rl := range user.Roles {
                if rl == req.Role {
                        valid = true
                        break
                }
        }
        if !valid {
                errResp(w, 400, "invalid_json", "user does not have that role")
                return
        }

        // Extract token from auth header
        authHdr := r.Header.Get("Authorization")
        token := ""
        if len(authHdr) > 7 && authHdr[:7] == "Bearer " {
                token = authHdr[7:]
        }

        if token != "" {
                h.Store.UpdateSessionRole(r.Context(), token, req.Role)
        }

        respond(w, 200, map[string]interface{}{
                "data": map[string]interface{}{
                        "activeRole": req.Role,
                        "roles":      user.Roles,
                },
        })
}

// ReadUIBootstrap
func (h *Handler) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
        userID := middleware.GetUserID(r.Context())
        user, err := h.Store.GetUserByID(r.Context(), userID)
        if err != nil {
                errResp(w, 401, "unauthorized", "user not found")
                return
        }

        samples, _ := h.Store.ListSamples(r.Context())
        requesterSamples := []map[string]interface{}{}
        for _, sm := range samples {
                if sm.RequesterID == userID {
                        requesterSamples = append(requesterSamples, map[string]interface{}{
                                "sampleId":  sm.ID,
                                "requestId": sm.RequestID,
                                "status":    sm.Status,
                        })
                }
        }

        ops := h.buildOperationsState(r.Context())

        respond(w, 200, map[string]interface{}{
                "data": map[string]interface{}{
                        "user": map[string]interface{}{
                                "userId": user.ID,
                                "username": user.Username,
                                "roles": user.Roles,
                        },
                        "serverTime":       time.Now().UTC(),
                        "requesterSamples": requesterSamples,
                        "operations":       ops,
                },
        })
}

func (h *Handler) buildOperationsState(ctx context.Context) interface{} {
        // Simplified version of operations state for bootstrap
        return models.OperationsState{
                Samples:                   []map[string]interface{}{},
                Workers:                   []map[string]interface{}{},
                Locations:                 []map[string]interface{}{},
                Connections:               []map[string]interface{}{},
                Routes:                    []map[string]interface{}{},
                Handoffs:                  []map[string]interface{}{},
                Delays:                    []map[string]interface{}{},
                Exceptions:                []map[string]interface{}{},
                AssignmentCountSpread:     0,
                IneligibleAssignmentCount: 0,
        }
}

