// ConfigureCapacity
func (h *Handler) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
        var req struct {
                ResourceID         string `json:"resourceId"`
                CapacityUnits      *int   `json:"capacityUnits"`
                CooledCapacityUnits *int  `json:"cooledCapacityUnits"`
        }
        if err := getReqBody(r, &req); err != nil {
                errResp(w, 400, "invalid_json", "invalid request body")
                return
        }

        units := 0
        cooled := 0
        if req.CapacityUnits != nil {
                units = *req.CapacityUnits
        }
        if req.CooledCapacityUnits != nil {
                cooled = *req.CooledCapacityUnits
        }

        if err := h.Store.SetLocationCapacity(r.Context(), req.ResourceID, units, cooled); err != nil {
                errResp(w, 500, "internal_error", "capacity update failed")
                return
        }

        h.writeAudit(r.Context(), middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "capacity.configured", "capacity", req.ResourceID, true, "")
        respond(w, 200, map[string]interface{}{
                "data": map[string]interface{}{
                        "resourceId":         req.ResourceID,
                        "capacityUnits":      units,
                        "cooledCapacityUnits": cooled,
                },
        })
}

// CreateConnection
func (h *Handler) CreateConnection(w http.ResponseWriter, r *http.Request) {
        var req struct {
                FromLocationID string `json:"fromLocationId"`
                ToLocationID   string `json:"toLocationId"`
                TravelMinutes  int    `json:"travelMinutes"`
                CostUnits      int    `json:"costUnits"`
                Cooled         bool   `json:"cooled"`
                Active         *bool  `json:"active"`
        }
        if err := getReqBody(r, &req); err != nil {
                errResp(w, 400, "invalid_json", "invalid request body")
                return
        }

        active := true
        if req.Active != nil {
                active = *req.Active
        }

        c := &models.Connection{
                ID:            uuid.New().String(),
                FromLocationID: req.FromLocationID,
                ToLocationID:  req.ToLocationID,
                TravelMinutes: req.TravelMinutes,
                CostUnits:     req.CostUnits,
                Cooled:        req.Cooled,
                Active:        active,
        }

        if err := h.Store.CreateConnection(r.Context(), c); err != nil {
                errResp(w, 409, "idempotency_conflict", "connection creation failed")
                return
        }

        h.writeAudit(r.Context(), middleware.GetUserID(r.Context()), middleware.GetRole(r.Context()), "connection.created", "connection", c.ID, true, "")
        respond(w, 201, map[string]interface{}{"data": c})
}

