        }
        if sm.PendingHandoffID != nil {
                resp["data"].(map[string]interface{})["pendingHandoffId"] = *sm.PendingHandoffID
        }
        if sm.LatestLocation != nil {
                resp["data"].(map[string]interface{})["latestLocation"] = sm.LatestLocation
        }
        if sm.LocationRecordedAt != nil {
                resp["data"].(map[string]interface{})["locationRecordedAt"] = *sm.LocationRecordedAt
        }

        respond(w, 200, resp)
}

